STATUS = "/printer/objects/query?webhooks=state&print_stats=state&print_task_config&purifier=power_detected&machine_state_manager&virtual_sdcard=is_active&gcode=commands"
EMPTY = {"", "NONE", "UNKNOWN", "N/A"}


class Blocked(RuntimeError):
    pass


def describe_head_changes(expected, actual):
    if not isinstance(expected, list) or not isinstance(actual, list):
        return "The loaded material or color changed after setup was opened."
    previous = {h.get("id"): h for h in expected}
    changes = []
    for head in sorted(actual, key=lambda h: h.get("id", -1)):
        old = previous.get(head.get("id"))
        if old is None:
            continue
        kind = old.get("type") != head.get("type")
        shade = old.get("color") != head.get("color")
        if kind or shade:
            what = "type and color" if kind and shade else "type" if kind else "color"
            changes.append("The filament %s in Head %d changed" % (what, head["id"] + 1))
        elif old.get("loaded") != head.get("loaded"):
            changes.append("The filament presence in Head %d changed" % (head["id"] + 1))
    return "; ".join(changes) + "." if changes else "The loaded material or color changed after setup was opened."


class HeadsChanged(Blocked):
    def __init__(self, message, expected=None, actual=None):
        super().__init__(message)
        self.changes = describe_head_changes(expected, actual)


def material(value):
    # Exact type equality after case/whitespace normalization. No family aliases.
    return str(value or "").strip().upper()


