FILAMENT_FAMILIES = ('HPP4GF25', 'ULTRAPA', 'BVOH', 'COPE', 'FLEX', 'HIPS', 'PA11', 'PA12', 'PAHT', 'PCTG', 'PEBA', 'PEEK', 'PEKK', 'PETG', 'PPSU', 'UNIV', 'ABS', 'ASA', 'EVA', 'PA6', 'PEI', 'PET', 'PHA', 'PLA', 'PPA', 'PPS', 'PSU', 'PVA', 'PVB', 'SBS', 'TPE', 'TPU', 'PA', 'PC', 'PE', 'PP')
FILAMENT_VENDOR_ALIASES = {
    "BAMBU LAB": ("BAMBU",),
    "COEX 3D": ("COEX",),
    "CREALITY": ("CR", "ENDER"),
    "FELIX PRINTERS": ("FELIX",),
    "LH STINGER": ("LHS",),
    "ORCA ARENA": ("ARENA",),
    "POLYMAKER": ("FIBERON", "PANCHROMA", "POLYLITE", "POLYTERRA", "POLYSONIC"),
    "PRUSA POLYMERS": ("PRUSAMENT",),
}

FILAMENT_NAME_OVERRIDES = {
    ("ADDNORTH", "PC BLEND HT LCF"): "PC BLEND HT LCF",
    ("COEX 3D", "NYLEX UNFILLED"): "PA",
    ("CREALITY", "FAST PLA"): "PLA",
    ("GENERIC", "ENABLER PLA"): "PLA",
    ("IQ MATERIALS", "FIBERTHREE PACF PRO P1"): "PA-CF",
    ("IQ MATERIALS", "FIBERTHREE PACF PRO P2"): "PA-CF",
    ("PEOPOLY", "LANCER ABS-GF"): "ABS-GF",
    ("PEOPOLY", "LANCER PLA-C"): "PLA",
    ("VOLUMIC", "PA6 CF20 (PERFORMANCE)"): "PA6-CF20",
    ("VOLUMIC", "PETG ESD (PERFORMANCE)"): "PETG",
}

FILAMENT_VARIANTS = ("FULL SPECTRUM", "TRANSLUCENT", "SILK", "MATTE", "WOOD",
                     "TOUGH", "AERO", "HF")


def material_tokens(value):
    return re.findall(r"[A-Z0-9]+", material(value))


def remove_material_vendor(name, vendor):
    vendor = material(vendor)
    if vendor:
        name = re.sub(r"(?<![A-Z0-9])" + re.escape(vendor) + r"(?![A-Z0-9])", " ", name)
    for alias in FILAMENT_VENDOR_ALIASES.get(vendor, ()):
        name = re.sub(r"^" + re.escape(alias) + r"(?:[\s_-]+|$)", "", name.strip())
    return name.strip(" _-")


def normalize_material_type(value):
    value = material(value)
    if value in {"TPU-AMS", "TPU AMS", "TPU FOR AMS"}:
        return "TPU"
    value = re.sub(r"(?:[ -]+)(?:BASIC|PRO|ESD|SNAPSPEED)$", "", value)
    return re.sub(r"[ _-]+([CG]F\d*)\b", r"-\1", value)


def project_material(kind, preset_name, vendor=None):
    kind = normalize_material_type(kind)
    preset = material(preset_name)
    raw = preset.split("@", 1)[0].strip()
    vendor = material(vendor or FILAMENT_PROFILE_VENDORS.get(preset) or FILAMENT_PROFILE_VENDORS.get(raw))
    name = remove_material_vendor(raw, vendor)
    override = FILAMENT_NAME_OVERRIDES.get((vendor, name))
    if override:
        return override, True
    support = re.search(r"\bSUPPORT FOR (PLA|ABS|PETG)\b", name)
    if support:
        return support[0], True

    family = material_family(kind)
    tokens = material_tokens(name)
    # A declared grade or filler takes precedence over details inferred from the profile name.
    if kind != family:
        return kind, True
    filler = re.search(r"(?<![A-Z0-9])" + re.escape(family) + r"[ _-]+([CG]F\d*)\b", name)
    if filler:
        kind += "-" + filler[1]
    if family == "PLA" and "HS" in tokens:
        kind += "-HS"
    if family == "ABS" and "HT" in tokens:
        kind += "-HT"
    details = []
    if family == "PC":
        details.extend(word for word in ("BLEND", "FR") if word in tokens)
    if family == "TPU":
        details.extend(dict.fromkeys(word for word in tokens if re.fullmatch(r"\d+[AD]", word)))
    if family in tokens or (family == "PLA" and "TOUGH" in tokens):
        details.extend(word for word in FILAMENT_VARIANTS
                       if re.search(r"(?<![A-Z0-9])" + word + r"(?![A-Z0-9])", name))
    if (vendor, name) in {("SUNLU", "PLA+"), ("NUMAKERS", "PLA+")}:
        kind += "+"
    return " ".join((kind, *details)), bool(name)


def project_filament(kind, presets, vendors, index):
    name, known = project_material(kind, presets[index] if index < len(presets) else None,
                                   vendors[index] if index < len(vendors) else None)
    return {"type": name, "variant_known": known}


def material_key(value):
    normalized = normalize_material_type(value)
    return tuple(sorted(material_tokens(normalized))) + (("+",) if normalized.endswith("+") else ())


def color(value):
    value = str(value or "").lstrip("#")
    return "#" + value[:6].upper() if re.fullmatch(r"[0-9a-fA-F]{6}(?:[0-9a-fA-F]{2})?", value) else "#C8CBD0"


def profile_values(value):
    """Host config vectors may arrive as native lists or serialized ; lists."""
    if value is None or value == "":
        return []
    if isinstance(value, (list, tuple)):
        return [str(item).strip() for item in value]
    if isinstance(value, str):
        return [item.strip() for item in next(csv.reader([value], delimiter=";", quotechar='"', escapechar="\\"))]
    raise Blocked("Unsupported filament profile data format.")


def number_vector(value):
    if value is None or value == "":
        return None
    try:
        result = [float(v) for v in next(csv.reader([str(value)], delimiter=","))]
        if not result or any(not math.isfinite(v) or v < 0 for v in result):
            raise ValueError()
        return result
    except (ValueError, csv.Error):
        raise Blocked("Invalid filament usage metadata. Re-slice this plate.")


def png_rgba(raw):
    """Decode native 8-bit RGB/RGBA PNG without premultiplying the ID alpha channel."""
    if raw[:8] != b'\x89PNG\r\n\x1a\n':
        raise ValueError('Not a PNG')
    pos=8; packed=[]; header=None
    while pos+12 <= len(raw):
        size=struct.unpack('>I',raw[pos:pos+4])[0];kind=raw[pos+4:pos+8];data=raw[pos+8:pos+8+size]
        if len(data)!=size:raise ValueError('Truncated PNG')
        if kind==b'IHDR':header=struct.unpack('>IIBBBBB',data)
        if kind==b'IDAT':packed.append(data)
        pos+=size+12
        if kind==b'IEND':break
    if header is None:raise ValueError('Missing PNG header')
    w,h,depth,mode,compression,filtering,interlace=header
    if not (0<w<=2048 and 0<h<=2048 and depth==8 and mode in (2,6) and compression==filtering==interlace==0):
        raise ValueError('Unsupported native thumbnail format')
    bpp=4 if mode==6 else 3;stride=w*bpp;expected=(stride+1)*h
    decoder=zlib.decompressobj();data=decoder.decompress(b''.join(packed),expected+1)
    if len(data)!=expected or not decoder.eof:raise ValueError('Invalid PNG pixels')
    out=bytearray();previous=bytearray(stride)
    for y in range(h):
        start=y*(stride+1);f=data[start];row=bytearray(data[start+1:start+1+stride])
        if f>4:raise ValueError('Invalid PNG filter')
        for x in range(stride):
            a=row[x-bpp] if x>=bpp else 0;b=previous[x];c=previous[x-bpp] if x>=bpp else 0
            if f==1:v=a
            elif f==2:v=b
            elif f==3:v=(a+b)//2
            elif f==4:
                p=a+b-c;pa,pb,pc=abs(p-a),abs(p-b),abs(p-c);v=a if pa<=pb and pa<=pc else b if pb<=pc else c
            else:v=0
            row[x]=(row[x]+v)&255
        if bpp==4:out.extend(row)
        else:
            for x in range(0,stride,3):out.extend(row[x:x+3]+b'\xff')
        previous=row
    return w,h,bytes(out)


def preview_mixed_recipes(config):
    """Preview-only virtual slots; they never become printer tool assignments."""
    def vector(key):
        value = config.get(key, [])
        return value if isinstance(value, list) else []
    flags = vector('filament_is_mixed')
    components = vector('filament_mixed_components')
    ratios = vector('filament_mixed_sublayer_ratios')
    gradients = vector('filament_mixed_gradient')
    ranges = vector('filament_mixed_gradient_range')
    curves = vector('filament_mixed_gradient_curve')
    per_parts = vector('filament_mixed_gradient_per_part')
    colors = vector('filament_colour')
    recipes = []
    for slot, enabled in enumerate(flags):
        if enabled not in (True, 1, '1') or slot >= len(components):
            continue
        try:
            ids = [int(v.strip()) - 1 for v in str(components[slot]).split(',')]
            if len(ids) < 2 or any(i < 0 or i >= len(flags) or i == slot for i in ids):
                continue
            weights = [float(v) for v in str(ratios[slot]).split(',')] if slot < len(ratios) and ratios[slot] else [1.0] * len(ids)
            if len(weights) != len(ids) or any(not math.isfinite(w) or w < 0 for w in weights) or sum(weights) <= 0:
                continue
            recipes.append(dict(slot=slot, components=ids, weights=weights,
                                gradient=slot < len(gradients) and gradients[slot] in (True, 1, '1'),
                                gradient_range=str(ranges[slot]) if slot < len(ranges) else '',
                                gradient_curve=str(curves[slot]) if slot < len(curves) else '',
                                gradient_per_part=slot < len(per_parts) and per_parts[slot] in (True, 1, '1'),
                                source_colors=[color(colors[i]) if i < len(colors) else None for i in ids],
                                source_color=color(colors[slot]) if slot < len(colors) else None))
        except (ValueError, TypeError):
            continue
    return recipes


def preview_paint_states(encoded):
    """Decode leaf filament IDs from one 3MF triangle's paint tree (zero based)."""
    if not encoded:
        return set()
    if not isinstance(encoded, str) or len(encoded) > 1024 * 1024:
        return set()
    try:
        codes = iter(int(char, 16) for char in reversed(encoded))
        remaining = 1
        slots = set()
        while remaining:
            code = next(codes)
            remaining -= 1
            split = code & 3
            if split:
                if split != 3 and code >> 2 == 3:
                    return set()
                remaining += split + 1
                continue
            state = code >> 2
            if state == 3:
                extension = next(codes)
                state = next(codes) + 18 if extension == 15 else extension + 3
            if state:
                slots.add(state - 1)
        # A facet is one complete tree, not a loose collection of hex digits.
        if next(codes, None) is not None:
            return set()
        return slots
    except (ValueError, StopIteration):
        return set()


def preview_painted_slots(archive, objects):
    """Read painted facets only from the selected plate's object/component trees."""
    import posixpath
    import xml.etree.ElementTree as ET
    names = {name.lower(): name for name in archive.namelist()}
    root_path = names.get('3d/3dmodel.model')
    if root_path is None:
        return set()
    cache = {}
    def local(name):
        return name.rsplit('}', 1)[-1]
    def attribute(element, name):
        return next((value for key, value in element.attrib.items() if local(key) == name), None)
    def resolve_path(base, reference):
        if not reference:
            return base
        path = posixpath.normpath(reference.lstrip('/') if reference.startswith('/') else posixpath.join(posixpath.dirname(base), reference))
        if path.startswith('../') or path == '..':
            return None
        return names.get(path.lower())
    def load(path):
        if path in cache:
            return cache[path]
        result = {}
        cache[path] = result
        if path is None or archive.getinfo(path).file_size > 256 * 1024 * 1024:
            return result
        # Stream geometry: do not retain vertices or triangle XML in memory.
        with archive.open(path) as stream:
            stack = []
            record = None
            triangle_index = 0
            for event, element in ET.iterparse(stream, events=('start', 'end')):
                tag = local(element.tag)
                if event == 'start':
                    stack.append(element)
                    if tag == 'object':
                        record = {'paint': set(), 'facets': [], 'components': []}
                        result[element.get('id')] = record
                        triangle_index = 0
                    continue
                if record is not None:
                    if tag == 'triangle':
                        states = preview_paint_states(attribute(element, 'paint_color') or attribute(element, 'mmu_segmentation'))
                        if states:
                            record['paint'].update(states)
                            record['facets'].append((triangle_index, states))
                        triangle_index += 1
                    elif tag == 'component':
                        record['components'].append((resolve_path(path, attribute(element, 'path')), element.get('objectid')))
                    elif tag == 'object':
                        record = None
                stack.pop()
                element.clear()
                if stack:
                    stack[-1].remove(element)
        return result
    painted = set()
    def walk(path, object_id, excluded=frozenset(), ranges=None, ancestors=frozenset()):
        key = (path, object_id)
        if path is None or key in ancestors or len(ancestors) > 64:
            return
        record = load(path).get(object_id)
        if record is None:
            return
        if ranges is None:
            painted.update(record['paint'])
        else:
            for index, states in record['facets']:
                if any(first <= index <= last for first, last in ranges):
                    painted.update(states)
        for child_path, child_id in record['components']:
            if child_id not in excluded:
                walk(child_path, child_id, ancestors=ancestors | {key})
    for obj in objects:
        excluded = set()
        ranges = []
        legacy_ranges = False
        for part in list(obj.findall('part')) + list(obj.findall('volume')):
            metadata = {m.get('key'): m.get('value', m.text or '') for m in part.findall('metadata')}
            kind = part.get('subtype', metadata.get('part_type', 'normal_part'))
            allowed = kind in ('normal_part', 'model_part', '0', 'modifier', 'parameter_modifier', '2')
            if not allowed:
                excluded.add(part.get('id'))
            if part.get('firstid') is not None and part.get('lastid') is not None:
                legacy_ranges = True
                if allowed:
                    try:
                        ranges.append((int(part.get('firstid')), int(part.get('lastid'))))
                    except (ValueError, TypeError):
                        pass
        walk(root_path, obj.get('id'), excluded, ranges if legacy_ranges else None)
    return painted


def preview_model_slots(archive, plate):
    """Read object/part assignments on one plate, independent of thumbnail pixels."""
    import xml.etree.ElementTree as ET
    name = 'Metadata/model_settings.config'
    if name not in archive.namelist() or archive.getinfo(name).file_size > 16 * 1024 * 1024:
        return None
    raw = archive.read(name)
    if b'<!DOCTYPE' in raw.upper() or b'<!ENTITY' in raw.upper():
        return None
    try:
        root = ET.fromstring(raw)
        def metadata(node):
            return {item.get('key'): item.get('value', item.text or '') for item in node.findall('metadata')}
        plates = root.findall('plate')
        target = next((item for item in plates if metadata(item).get('plater_id') == str(plate)), None)
        if target is None:
            return None
        object_ids = {metadata(item).get('object_id') for item in target.findall('model_instance')}
        objects = {item.get('id'): item for item in root.findall('object')}
        slots = set()
        def assigned(value, inherited=1):
            try:
                number = int(value)
                return number if number > 0 else inherited
            except (ValueError, TypeError):
                return inherited
        for object_id in object_ids:
            obj = objects.get(object_id)
            if obj is None:
                return None
            default = assigned(metadata(obj).get('extruder'))
            parts = obj.findall('part') or obj.findall('volume')
            if not parts:
                slots.add(default - 1)
            for part in parts:
                kind = part.get('subtype', metadata(part).get('part_type', 'normal_part'))
                if kind not in ('normal_part', 'model_part', '0', 'modifier', 'parameter_modifier', '2'):
                    continue
                values = metadata(part)
                # A modifier without a colour override does not introduce a colour.
                if kind in ('modifier', 'parameter_modifier', '2') and not values.get('extruder'):
                    continue
                slots.add(assigned(values.get('extruder'), default) - 1)
        # Painted faces can use filaments/mixes absent from object assignments
        # and can be occluded in the exported thumbnail.
        try:
            selected_objects = [objects[object_id] for object_id in object_ids]
            slots.update(preview_painted_slots(archive, selected_objects))
        except (ET.ParseError, ValueError, TypeError, KeyError, OSError, RuntimeError):
            pass  # A failed optional paint read must not discard assignments.
        return sorted(slot for slot in slots if 0 <= slot < 64)
    except (ET.ParseError, ValueError, TypeError):
        return None


def extract_pairs(path, *, plate=None):
    if plate is not None and (type(plate) is not int or plate < 1):
        raise ValueError("Invalid plate index")
    pairs=[]
    with zipfile.ZipFile(path) as archive:
        names=archive.namelist()
        mixed = []
        if 'Metadata/project_settings.config' in names:
            info = archive.getinfo('Metadata/project_settings.config')
            if info.file_size <= 4 * 1024 * 1024:
                try:
                    config = json.loads(archive.read(info))
                    mixed = preview_mixed_recipes(config)
                except (ValueError, TypeError, KeyError):
                    pass
        for name in names:
            match=re.fullmatch(r'Metadata/plate_(\d+)\.png',name,re.I)
            if not match:continue
            number=match[1]
            if plate is not None and int(number) != plate:
                continue
            mask=next((n for n in names if re.fullmatch(r'Metadata/(?:plate_no_light_'+number+'|plate_'+number+r'_no_light)\.png',n,re.I)),None)
            if not mask:continue
            def read(n):
                if archive.getinfo(n).file_size>16*1024*1024:raise ValueError('Thumbnail too large')
                return png_rgba(archive.read(n))
            w,h,lit=read(name);mw,mh,flat=read(mask)
            if (w,h)!=(mw,mh):raise ValueError('Thumbnail sizes differ')
            counts={}
            for i in range(0,len(lit),4):
                if lit[i+3] and 255-flat[i+3]<64:
                    slot=255-flat[i+3];counts[slot]=counts.get(slot,0)+1
            # Empty plates have no model pixels; they must not discard other plates.
            if not counts:
                continue
            pairs.append(dict(model_slots=preview_model_slots(archive, int(number)),mixed=mixed,plate=int(number),width=w,height=h,lit=base64.b64encode(lit).decode(),flat=base64.b64encode(flat).decode(),slots=sorted(counts),pixel_counts=counts))
    if not pairs:
        raise ValueError('Orca did not export a normal/no-light thumbnail pair. PNG files: '+', '.join(n for n in names if n.lower().endswith('.png'))[:1000])
    return sorted(pairs,key=lambda p:p['plate'])


def wait_for_native_window_close(window):
    """Do not release the export worker while the macOS modal loop still owns its dialog.

    UiWindow.is_open() follows registry lifetime, not the early on_close callback.
    The registry entry is removed by destruction after ShowModal() has returned.
    """
    if window is None:
        return
    while window.is_open():
        time.sleep(0.05)


def plate_details(lines, config_value, filename):
    """Read Orca metadata without editing G-code or inferring usage from filenames."""
    stats = {}
    thumbnail = None
    largest = 0
    collecting = None
    area = 0
    encoded_length = 0
    layer_markers = 0
    for line in lines:
        if re.match(r"^;\s*(?:CHANGE_LAYER|LAYER_CHANGE)\s*$", line.strip()):
            layer_markers += 1
        match = re.match(r"^;\s*([^=]+?)\s*=\s*(.*?)\s*$", line)
        if match and len(match[1]) < 160:
            stats[match[1].strip()] = match[2].strip()
        begin = re.match(r"^;\s*thumbnail begin (\d+)x(\d+)", line)
        if begin:
            w, h = int(begin[1]), int(begin[2])
            collecting = [] if 0 < w <= 2048 and 0 < h <= 2048 else None
            area = w * h
            encoded_length = 0
        elif collecting is not None:
            if re.match(r"^;\s*thumbnail end", line):
                try:
                    encoded = "".join(collecting)
                    raw = base64.b64decode(encoded, validate=True)
                    if (len(raw) >= 33 and raw[:8] == b"\x89PNG\r\n\x1a\n"
                            and raw[12:16] == b"IHDR" and len(raw) <= 512 * 1024
                            and all(0 < d <= 2048 for d in struct.unpack(">II", raw[16:24])) and area > largest):
                        thumbnail, largest = "data:image/png;base64," + encoded, area
                except (ValueError, struct.error):
                    pass
                collecting = None
            elif encoded_length + len(line) <= 700000:
                collecting.append(line.removeprefix(";").strip())
                encoded_length += len(line)
            else:
                collecting = None

    def setting(key):
        value = stats.get(key)
        return value if value not in (None, "") else config_value(key)

    types = profile_values(setting("filament_type"))
    presets = profile_values(setting("filament_settings_id"))
    vendors = profile_values(setting("filament_vendor"))
    colors = profile_values(setting("filament_colour"))
    mm = number_vector(stats.get("filament used [mm]"))
    grams = number_vector(stats.get("filament used [g]"))
    usage = mm if mm is not None else grams
    warning = ""
    if usage is None:
        used = []
        warning = "Used-color metadata is missing. Re-slice with filament usage statistics."
    else:
        used = [i for i, value in enumerate(usage) if value > 0]
        if not used:
            warning = "No used model colors were found in the plate metadata."
    if len(usage or []) > 32:
        raise Blocked("The plate exceeds the U1 logical tool limit.")
    vitrification = number_vector(stats.get("temperature_vitrification"))
    high_temperature = number_vector(stats.get("filament_is_high_temperature"))
    filaments = []
    for i in used:
        if i >= len(types) or material(types[i]) in EMPTY:
            raise Blocked("Missing material type for model color %d. Re-slice the plate." % (i + 1))
        filaments.append({"id": i, **project_filament(types[i], presets, vendors, i),
                          "color": color(colors[i] if i < len(colors) else None),
                          "grams": grams[i] if grams is not None and i < len(grams) else None,
                          "temperature_vitrification": vitrification[i] if vitrification is not None and i < len(vitrification) else None,
                          "filament_is_high_temperature": bool(high_temperature[i]) if high_temperature is not None and i < len(high_temperature) else False})
    total = sum(grams) if grams is not None else None
    if total is None and stats.get("total filament used [g]"):
        parsed = number_vector(stats["total filament used [g]"])
        total = sum(parsed) if parsed else None
    change_text = stats.get("total filament change")
    tool_changes = int(change_text) if change_text and re.fullmatch(r"\d{1,9}", change_text) else None
    layer_text = stats.get("total layer number") or stats.get("total layers count")
    layers = int(layer_text) if layer_text and re.fullmatch(r"[1-9]\d{0,6}", layer_text) else (layer_markers or None)
    return {"tool_changes": tool_changes, "layers": layers, "project": os.path.basename(str(filename).replace("\\", "/")),
            "filaments": filaments, "time": stats.get("estimated printing time (normal mode)"),
            "grams": total, "thumbnail": thumbnail, "scope": "plate", "warning": warning}


def read_plate(path, config_value, filename):
    if os.path.getsize(path) > 1024 * 1024 * 1024:
        raise Blocked("G-code is too large for this preview.")
    with open(path, "r", encoding="utf-8", errors="replace") as stream:
        # A streaming parser avoids loading the whole print into memory.
        return plate_details(stream, config_value, filename)


def working_job_path(ctx):
    """Use only this export's authoritative working copy, including earlier plugins.

    Never recover from output_name, an old slice cache, or a file on the printer:
    those may refer to a different or not-yet-postprocessed job.
    """
    path = os.fspath(ctx.gcode_path) if ctx.gcode_path else ""
    if not path or not os.path.isfile(path):
        raise Blocked("OrcaSlicer did not provide an existing working G-code file for this send. Re-slice the plate and send again; no printer settings were sent.")
    if os.path.getsize(path) == 0:
        raise Blocked("OrcaSlicer's working G-code file is empty. Re-slice the plate and send again; no printer settings were sent.")
    return path


def material_family(value):
    value = material(value)
    tokens = material_tokens(value)
    if tokens[:2] == ["SUPPORT", "FOR"]:
        return " ".join(tokens)
    if re.match(r"^PA(?:6|11|12|66)(?=$|[ +_-])", value):
        return "PA"
    return next((family for family in FILAMENT_FAMILIES if family in tokens), value)


def compatible(filament, head):
    return (head_presence(head) is True and known_material(head.get("type")) and material(filament.get("type")) not in EMPTY
            and material_family(filament.get("type")) == material_family(head.get("type")))


def suggest_mapping(filaments, heads, fixed=None):
    """Prefer distinct compatible heads, then total color distance, then material detail."""
    fixed = dict(fixed or {})
    heads = sorted(heads, key=lambda head: head["id"])
    reserved = {head_id for head_id in fixed.values()}
    states = {0: (0, 0, ())}
    remaining = [f for f in sorted(filaments, key=lambda f: f["id"]) if str(f["id"]) not in fixed]
    for f in remaining:
        ranked = [(index, *mapping_score(f, h)) for index, h in enumerate(heads) if compatible(f, h)]
        next_states = {}
        for mask, (distance, differences, picks) in states.items():
            options = [(len(heads), 0, 0)] + [
                (index, delta, difference) for index, delta, difference in ranked
                if heads[index]["id"] not in reserved and not mask & (1 << index)
            ]
            for index, delta, difference in options:
                new_mask = mask | (1 << index) if index < len(heads) else mask
                candidate = (distance + delta, differences + difference, (*picks, index))
                if new_mask not in next_states or candidate < next_states[new_mask]:
                    next_states[new_mask] = candidate
        states = next_states
    _, (_, _, picks) = min(states.items(), key=lambda item: (-item[0].bit_count(), *item[1]))
    for f, index in zip(remaining, picks):
        if index < len(heads):
            fixed[str(f["id"])] = heads[index]["id"]
        else:
            # More project slots than available heads can share a compatible head.
            candidates = [h for h in heads if compatible(f, h)]
            if candidates:
                fixed[str(f["id"])] = min(candidates, key=lambda h: mapping_score(f, h))["id"]
    return fixed


def mapping_score(filament, head):
    first, second = color(filament.get("color")), color(head.get("color"))
    distance = sum((int(first[i:i+2], 16) - int(second[i:i+2], 16)) ** 2 for i in (1, 3, 5))
    same_detail = filament.get("variant_known", True) and material_key(filament["type"]) == material_key(head["type"])
    return distance, int(not same_detail)


def unassigned_materials(filaments, heads, mapping):
    heads = heads if isinstance(heads, list) else []
    mapping = mapping if isinstance(mapping, dict) else {}
    return sorted({material(f["type"]) for f in filaments
                   if not any(h.get("id") == mapping.get(str(f["id"])) and compatible(f, h) for h in heads)})



def native_cancel_supported(version):
    """Use native cancellation from Orca 2.5 onward, including prereleases."""
    match = re.fullmatch(
        r"v?([0-9]+)\.([0-9]+)(?:\.[0-9]+)?(?:[-+][0-9a-z][0-9a-z.+-]*)?",
        str(version or "").strip(),
        re.I,
    )
    return match is not None and tuple(map(int, match.groups())) >= (2, 5)


def native_fallback_mapping(filaments, heads, mapping):
    """Keep compatible choices; unmatched logical T0–T3 use their own index."""
    mapping = mapping if isinstance(mapping, dict) else {}
    result = {}
    for filament in filaments:
        logical = filament["id"]
        selected = mapping.get(str(logical))
        head = next((h for h in heads if h.get("id") == selected), None)
        if head is not None and compatible(filament, head):
            result[str(logical)] = selected
        elif type(logical) is int and 0 <= logical < 4:
            result[str(logical)] = logical
        else:
            raise Blocked("No automatic physical head is known for this filament. Return to SnapSend and assign a head.")
    return result

def validate_setup(filaments, heads, mapping, prefs, *, allow_material_mismatch=False, allow_empty_heads=False):
    if not filaments:
        raise Blocked("No used model colors to validate.")
    if len(heads) != 4 or [h.get("id") for h in heads] != list(range(4)):
        raise Blocked("Four physical heads T0–T3 are required.")
    if not isinstance(mapping, dict) or set(mapping) != {str(f["id"]) for f in filaments}:
        raise Blocked("Assign every model color before checking setup.")
    for f in filaments:
        target = mapping[str(f["id"])]
        if type(target) is not int or not 0 <= target < 4:
            raise Blocked("Choose a physical head T0–T3 for every model color.")
        if not assignment_allowed(f, heads[target], allow_material_mismatch, allow_empty_heads):
            raise Blocked("Model color %d cannot use T%d: empty head or different material." % (f["id"] + 1, target))
    if (not isinstance(prefs, dict) or not {"timelapse", "leveling", "flow"} <= set(prefs)
            or set(prefs) - {"timelapse", "leveling", "flow", "flow_heads"}
            or any(type(prefs[k]) is not bool for k in ("timelapse", "leveling", "flow"))):
        raise Blocked("Invalid print preferences.")
    if "flow_heads" in prefs and not valid_flow_heads(prefs["flow_heads"]):
        raise Blocked("Invalid calibration toolhead selection.")
    return {"mapping": dict(mapping), "preferences": dict(prefs)}


def read_heads(task):
    arrays = [task.get(k) for k in ("filament_exist", "filament_type", "filament_color_rgba", "filament_sub_type")]
    if any(not isinstance(a, list) or len(a) != 4 for a in arrays[:3]):
        raise Blocked("Incomplete print_task_config: four physical heads must be reported.")
    exists, kinds, colors, subtypes = arrays
    if any(type(v) is not bool for v in exists) or any(not isinstance(v, str) for v in kinds):
        raise Blocked("Invalid filament presence or type data from the U1.")
    result = []
    for i in range(4):
        kind = material(kinds[i])
        sub = material(subtypes[i]) if isinstance(subtypes, list) and i < len(subtypes) else ""
        if sub not in {"", "GENERIC", "NONE", "UNKNOWN"}:
            suffix = "-" + sub if sub in {"CF", "GF"} else " " + sub
            if not kind.endswith(suffix):
                kind += suffix
        result.append({"id": i, "type": normalize_material_type(kind), "color": color(colors[i]),
                       "loaded": exists[i] is True and material(kinds[i]) not in EMPTY})
    return result


COVER_MODES = {"auto", "keep-warm", "weak", "strong", "off"}
DEFAULT_PREFS = {"timelapse": False, "leveling": True, "flow": False, "cover": "auto", "flow_heads": [0, 1, 2, 3]}


def valid_flow_heads(value):
    return (isinstance(value, list) and len(value) <= 4 and
            all(type(i) is int and 0 <= i < 4 for i in value) and len(set(value)) == len(value))


def clean_manual_cover(value):
    if not isinstance(value, dict):
        return {}
    presets = ("strong", "weak", "internal")
    preset = value.get("preset")
    profiles = value.get("profiles")
    cleaned = {}
    if preset in presets:
        cleaned["preset"] = preset
    if not isinstance(profiles, dict):
        return cleaned

    valid_profiles = {}
    for key in presets:
        profile = profiles.get(key)
        if not isinstance(profile, dict) or type(profile.get("preheat")) is not bool:
            continue
        values = profile.get("values")
        if not isinstance(values, list) or len(values) != 6 or any(type(item) is not int for item in values[:5]):
            continue
        exhaust, inner, target, alarm, delay, preheat_temp = values
        if not profile["preheat"] and preheat_temp is None:
            preheat_temp = 45
        if type(preheat_temp) is not int:
            continue
        if not (0 <= inner <= 100 and inner % 5 == 0 and
                0 <= delay <= 1800 and 1 <= preheat_temp <= 100):
            continue
        if key == "internal":
            if exhaust != 0 or inner < 10 or target != 45 or alarm != 0:
                continue
        elif not (1 <= exhaust <= 100 and (exhaust == 1 or exhaust % 5 == 0) and
                  1 <= target < alarm <= 100):
            continue
        valid_profiles[key] = {"values": [exhaust, inner, target, alarm, delay, preheat_temp],
                               "preheat": profile["preheat"]}
    cleaned["profiles"] = valid_profiles
    return cleaned


def clean_preferences(value):
    if not isinstance(value, dict):
        return dict(DEFAULT_PREFS, flow_heads=[0, 1, 2, 3])
    return {**{k: value[k] if type(value.get(k)) is bool else DEFAULT_PREFS[k]
               for k in ("timelapse", "leveling", "flow")},
            "flow_heads": sorted(value["flow_heads"]) if valid_flow_heads(value.get("flow_heads")) else [0, 1, 2, 3],
            "manual_cover": clean_manual_cover(value.get("manual_cover")),
            "cover": value.get("cover") if value.get("cover") in ("auto", "off", "manual") else "auto"}


def preference_key(address):
    identity = str(address or "").strip().rstrip("/").lower()
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()[:24]


# Process plugins stores a preset override; capability.save_config stores the base.
# Keep the most recent shared settings in the registered Settings script, whose
# capability has no process-preset override. Native saves carry the same revision.
SETTINGS_SCRIPT_OWNER = None
SHARED_SETTINGS_KEYS = ('language', 'theme', 'debug_mode', 'auto_pipeline',
                        'update_job_preview', 'update_job_colors',
                        'allow_material_mismatch', 'allow_empty_heads', 'allow_manual_cover',
                        'show_snapsend_tab', 'pending_pipeline_removal')
SHARED_SETTINGS_LOCK = threading.RLock()

def settings_revision(config):
    value = config.get('settings_revision', 0)
    return value if type(value) is int and value >= 0 else 0

def stored_shared_settings():
    if SETTINGS_SCRIPT_OWNER is None:
        return {}
    value = json.loads(SETTINGS_SCRIPT_OWNER.get_config() or '{}')
    value = value.get('shared_settings', {}) if isinstance(value, dict) else {}
    return value if isinstance(value, dict) else {}

def read_native_config(owner):
    value = json.loads(owner.get_config() or "{}")
    value = value if isinstance(value, dict) else {}
    if owner is not None and owner is globals().get('SETTINGS_OWNER'):
        with SHARED_SETTINGS_LOCK:
            shared = stored_shared_settings()
            if settings_revision(shared) > settings_revision(value):
                value.update({key: shared[key] for key in (*SHARED_SETTINGS_KEYS, 'settings_revision') if key in shared})
    return value


def promote_native_settings(owner):
    """Copy a newer committed preset save into the shared/base stores.

    Native config pages can only save a preset override. Never edit a preset
    here: promotion writes capability config only, including during an active send.
    Preserve the native revision so observing it again is a no-op.
    """
    if SETTINGS_SCRIPT_OWNER is None:
        return False
    with SHARED_SETTINGS_LOCK:
        config = json.loads(owner.get_config() or '{}')
        if not isinstance(config, dict):
            return False
        shared = stored_shared_settings()
        if settings_revision(config) <= settings_revision(shared):
            return False
        record = json.loads(SETTINGS_SCRIPT_OWNER.get_config() or '{}')
        if not isinstance(record, dict):
            record = {}
        record['shared_settings'] = {key: config[key] for key in (*SHARED_SETTINGS_KEYS, 'settings_revision') if key in config}
        if owner._save_base_config(json.dumps(config)) is False:
            raise ValueError('Could not save the shared base settings.')
        if SETTINGS_SCRIPT_OWNER.save_config(json.dumps(record)) is False:
            raise ValueError('Could not promote native settings to shared settings.')
        return True


def save_shared_settings(owner, config):
    with SHARED_SETTINGS_LOCK:
        shared = stored_shared_settings()
        revision = max(int(time.time() * 1000), settings_revision(shared) + 1,
                       settings_revision(config) + 1)
        updated = dict(config, settings_revision=revision)
        if owner._save_base_config(json.dumps(updated)) is False:
            return False
        if SETTINGS_SCRIPT_OWNER is not None:
            record = json.loads(SETTINGS_SCRIPT_OWNER.get_config() or '{}')
            if not isinstance(record, dict):
                record = {}
            record['shared_settings'] = {key: updated[key] for key in (*SHARED_SETTINGS_KEYS, 'settings_revision') if key in updated}
            if SETTINGS_SCRIPT_OWNER.save_config(json.dumps(record)) is False:
                return False
        return True


def load_preview_head_colors(owner):
    try:
        return read_native_config(owner).get("preview_head_colors") is not False
    except (AttributeError, ValueError, TypeError, RuntimeError):
        return True


def save_preview_head_colors(owner, enabled):
    if type(enabled) is not bool:
        raise ValueError("Invalid preview display preference")
    updated = dict(read_native_config(owner), preview_head_colors=enabled)
    if owner.save_config(json.dumps(updated)) is False:
        raise ValueError("Preview display preference could not be saved")
    return enabled


def load_debug_mode(owner):
    try:
        return read_native_config(owner).get("debug_mode") is True
    except (AttributeError, ValueError, TypeError, RuntimeError):
        return False


