def load_preferences(owner, address):
    try:
        records = read_native_config(owner).get("printers", {})
        return clean_preferences(records.get(preference_key(address))) if isinstance(records, dict) else clean_preferences(None)
    except (AttributeError, ValueError, TypeError, RuntimeError):
        return dict(DEFAULT_PREFS, flow_heads=[0, 1, 2, 3])


def save_preferences(owner, address, value):
    prefs = clean_preferences(value)
    config = read_native_config(owner)
    records = config.get("printers", {})
    if not isinstance(records, dict):
        records = {}
    key = preference_key(address)
    previous = clean_preferences(records.get(key)).get("manual_cover", {})
    manual = prefs["manual_cover"]
    prefs["manual_cover"] = {**previous, **manual, "profiles": {
        **previous.get("profiles", {}), **manual.get("profiles", {}),
    }}
    records[key] = prefs
    config["printers"] = records
    if not owner.save_config(json.dumps(config)):
        raise ValueError("OrcaSlicer could not save plugin preferences.")
    return prefs


def load_assignments(owner, address):
    try:
        records = read_native_config(owner).get("assignments", {})
        value = records.get(preference_key(address), []) if isinstance(records, dict) else []
        return value if isinstance(value, list) and len(value) <= 32 else []
    except (AttributeError, ValueError, TypeError, RuntimeError):
        return []


def save_assignments(owner, address, filaments, heads, mapping):
    if not isinstance(mapping, dict):
        return []
    saved = []
    for f in filaments:
        target = mapping.get(str(f["id"]))
        h = next((h for h in heads if type(target) is int and h["id"] == target), None)
        if h is not None and assignment_allowed(f, h, **assignment_options(owner)):
            saved.append({"id": f["id"], "type": material(f["type"]),
                          "color": color(f.get("color")), "head": target})
    config = read_native_config(owner)
    records = config.get("assignments", {})
    if not isinstance(records, dict):
        records = {}
    records[preference_key(address)] = saved
    config["assignments"] = records
    if not owner.save_config(json.dumps(config)):
        raise ValueError("OrcaSlicer could not save filament assignments.")
    return saved


def restore_assignments(filaments, heads, saved):
    fixed = {}
    by_id = {h["id"]: h for h in heads}
    for f in filaments:
        previous = next((r for r in saved if isinstance(r, dict) and r.get("id") == f["id"]), None)
        head_id = previous.get("head") if previous else None
        if type(head_id) is int and head_id in by_id and compatible(f, by_id[head_id]):
            fixed[str(f["id"])] = head_id
    return fixed


def snapshot(response):
    if not isinstance(response, dict):
        raise Blocked("Missing Moonraker status response.")
    status = response.get("status", {})
    state = status.get("print_stats", {}).get("state")
    task = status.get("print_task_config")
    if not isinstance(task, dict):
        raise Blocked("Stock U1 print_task_config is unavailable.")
    purifier = status.get("purifier")
    detected = purifier.get("power_detected") if isinstance(purifier, dict) else None
    return {"raw_state": state, "klippy_ready": status.get("webhooks", {}).get("state") == "ready", "cover_present": detected if type(detected) is bool else None, "heads": read_heads(task), "task": task, "idle": settings_idle(status), "commands": status.get("gcode", {}).get("commands"), "state": {"standby": "Ready", "complete": "Ready", "cancelled": "Ready", "printing": "Printing", "paused": "Paused", "error": "Error"}.get(state, "Unknown")}



class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise Blocked("Printer HTTP redirects are blocked. Correct the profile address.")


LIVE_STATUS = '/printer/objects/query?webhooks=state&print_stats=state&machine_state_manager'
WORKSPACE_LIVE_STATUS = STATUS.replace("&purifier=power_detected", "").replace("&gcode=commands", "")
def live_snapshot(result):
    status=result.get('status',{}) if isinstance(result,dict) else {}
    web=status.get('webhooks',{}).get('state')
    state=status.get('print_stats',{}).get('state')
    machine=status.get('machine_state_manager',{}).get('main_state')
    idle=web=='ready' and state in ('standby','complete','cancelled') and ((type(machine)is int and machine==0) or machine=='IDLE')
    label='Error' if web in ('error','shutdown') or state=='error' else 'Unavailable' if web!='ready' else 'Printing' if state=='printing' else 'Paused' if state=='paused' else 'Ready' if idle else 'Printer is busy' if machine is not None else 'Unknown'
    return {'kind':'live_status','state':label,'idle':idle}

class Moonraker:
    def __init__(self, address, api_key=""):
        address = str(address or "").strip().strip('"')
        if "://" not in address:
            address = "http://" + address
        parts = urllib.parse.urlsplit(address)
        if parts.scheme not in {"http", "https"} or not parts.hostname or parts.username or parts.password or parts.query or parts.fragment or parts.path not in {"", "/"}:
            raise Blocked("Set a plain Moonraker host/IP and optional port in the active printer profile.")
        try:
            _ = parts.port
        except ValueError:
            raise Blocked("Invalid printer port.")
        self.base = address.rstrip("/")
        self.api_key = api_key
        self.settings_post_count = 0
        self.request_stats = None
        # No system proxy, redirects, port scanning or fallback to another printer.
        self.opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect())

    def call(self, path):
        if path not in {STATUS, LIVE_STATUS, WORKSPACE_LIVE_STATUS, "/machine/system_info"}:
            raise Blocked("Only the read-only status query is allowed.")
        headers = {"Accept": "application/json"}
        if self.api_key:
            headers["X-Api-Key"] = self.api_key
        req = urllib.request.Request(self.base + path, headers=headers, method="GET")
        try:
            with self.opener.open(req, timeout=6) as stream:
                raw = stream.read(2 * 1024 * 1024 + 1)
            if len(raw) > 2 * 1024 * 1024:
                raise Blocked("Printer response is too large.")
            payload = json.loads(raw)
        except PermissionError:
            raise Blocked("Network permission was denied. Allow this printer URL in OrcaSlicer and retry.")
        except (OSError, ValueError):
            raise Blocked("Moonraker request failed. Check the profile IP/port, access key and printer connection. No automatic retry.")
        if not isinstance(payload, dict) or payload.get("error") is not None or "result" not in payload:
            raise Blocked("Moonraker reported an error or an invalid response. Settings could not be read. OrcaSlicer sending is not blocked.")
        return payload["result"]

    def send_settings(self, script):
        # No arbitrary G-code bridge: only this narrowly defined stock settings batch.
        lines = script.splitlines() if isinstance(script, str) else []
        if not 3 <= len(lines) <= 34 or len(script) > 4096:
            raise Blocked("Invalid settings batch.")
        logical = set()
        physical = set()
        for line in lines[:-2]:
            match = re.fullmatch(r"SET_PRINT_EXTRUDER_MAP CONFIG_EXTRUDER=(\d{1,2}) MAP_EXTRUDER=([0-3])", line)
            if not match or int(match[1]) > 31 or int(match[1]) in logical:
                raise Blocked("Invalid mapping command.")
            logical.add(int(match[1])); physical.add(int(match[2]))
        if lines[-2] != "SET_PRINT_USED_EXTRUDERS EXTRUDERS=" + ",".join(map(str, sorted(physical))):
            raise Blocked("Invalid used-head command.")
        if not re.fullmatch(r"SET_PRINT_PREFERENCES BED_LEVEL=[01] FLOW_CALIBRATE=[01] TIME_LAPSE_CAMERA=[01](?: FLOW_CALIBRATE_EXTRUDERS=(?:[0-3](?:,[0-3]){0,3}|-1))?", lines[-1]):
            raise Blocked("Invalid preferences command.")
        headers = {"Accept": "application/json", "Content-Type": "application/json"}
        if self.api_key:
            headers["X-Api-Key"] = self.api_key
        req = urllib.request.Request(self.base + SETTINGS_ENDPOINT,
              data=json.dumps({"script": script}).encode("utf-8"), headers=headers, method="POST")
        try:
            self.settings_post_count += 1
            if self.request_stats is not None:
                self.request_stats["post_count"] += 1
            with self.opener.open(req, timeout=6) as response:
                raw = response.read(65537)
            if len(raw) > 65536:
                raise ValueError("oversized response")
            payload = json.loads(raw)
        except (OSError, ValueError):
            raise Blocked("Settings request was not confirmed. No automatic retry.")
        if not isinstance(payload, dict) or payload.get("error") is not None or payload.get("result") != "ok":
            raise Blocked("The printer did not acknowledge the settings batch.")

    def device_name(self):
        try:
            info = self.call("/machine/system_info")
            name = info.get("system_info", {}).get("product_info", {}).get("device_name")
            if isinstance(name, str):
                return " ".join(name.split())[:64]
        except (Blocked, AttributeError, TypeError):
            pass
        return ""

    def read(self):
        result = snapshot(self.call(STATUS))
        if True:
            try:
                raw = V2_RUNTIME["V2Printer"](self.base, self.api_key).read()
                detail = V2_RUNTIME["actual_heads"](raw)
                result["head_display_states"] = {str(h["id"]): {"loaded": h["loaded"], "inserted": h["feed"].get("filament_detected")} for h in detail}
            except Exception:
                result["head_display_states"] = {}
        for head in result['heads']:
            state = result.get('head_display_states', {}).get(str(head['id']), {})
            head['inserted'] = True if head.get('loaded') else state.get('inserted')
            if head['inserted'] is False:
                head['type'] = ''
                head['color'] = '#C8CBD0'
        return result


# Stock U1 protocol only. These settings do not initiate motion or printing.
SETTINGS_ENDPOINT = "/printer/gcode/script"
COVER_COMMANDS = {
    "strong": "SET_PURIFIER_MODE MODE=1 DESIRE_TEMP=42 ALARM_TEMP=48 FAN_SPEED=0.6 DELAY_OFF=0",
    "weak": "SET_PURIFIER_MODE MODE=1 DESIRE_TEMP=45 ALARM_TEMP=51 FAN_SPEED=0.6 DELAY_OFF=0",
    "keep-warm": "SET_PURIFIER_MODE MODE=3 DESIRE_TEMP=45 FAN_SPEED=0.6 DELAY_OFF=600",
    "off": "SET_PURIFIER_MODE MODE=0 EXHAUST_FAN_DELAY_OFF=0 INNER_FAN_DELAY_OFF=0",
}


def settings_script(filaments, heads, mapping, preferences, *, allow_material_mismatch=False, allow_empty_heads=False):
    validate_setup(filaments, heads, mapping, preferences, allow_material_mismatch=allow_material_mismatch, allow_empty_heads=allow_empty_heads)
    if any(type(f["id"]) is not int or not 0 <= f["id"] < 32 for f in filaments):
        raise Blocked("Logical tool index must be between 0 and 31.")
    pairs = sorted((f["id"], mapping[str(f["id"])]) for f in filaments)
    commands = [f"SET_PRINT_EXTRUDER_MAP CONFIG_EXTRUDER={logical} MAP_EXTRUDER={physical}"
                for logical, physical in pairs]
    commands.append("SET_PRINT_USED_EXTRUDERS EXTRUDERS=" + ",".join(map(str, sorted({h for _, h in pairs}))))
    commands.append("SET_PRINT_PREFERENCES BED_LEVEL=%d FLOW_CALIBRATE=%d TIME_LAPSE_CAMERA=%d" %
                    (preferences["leveling"], preferences["flow"], preferences["timelapse"]))
    if "flow_heads" in preferences:
        # Stock parser accepts an index list, not a boolean mask. -1 selects none.
        selected = ",".join(map(str, sorted(preferences["flow_heads"]))) or "-1"
        commands[-1] += " FLOW_CALIBRATE_EXTRUDERS=" + selected
    return "\n".join(commands)


def verify_task_settings(task, mapping, preferences):
    table, used = task.get("extruder_map_table"), task.get("extruders_used")
    if not isinstance(table, list) or not isinstance(used, list) or len(used) != 4:
        raise Blocked("The printer did not confirm its applied tool settings.")
    if any(int(k) >= len(table) or type(table[int(k)]) is not int or table[int(k)] != v for k, v in mapping.items()):
        raise Blocked("The printer did not confirm the selected head mapping.")
    if any(type(v) is not bool for v in used) or used != [i in mapping.values() for i in range(4)]:
        raise Blocked("The printer did not confirm the used heads.")
    for key, field in (("leveling", "auto_bed_leveling"), ("flow", "flow_calibrate"), ("timelapse", "time_lapse_camera")):
        if type(task.get(field)) is not bool or task[field] != preferences[key]:
            raise Blocked("The printer did not confirm the selected print preferences.")
    if "flow_heads" in preferences:
        actual = task.get("flow_calib_extruders")
        if (not isinstance(actual, list) or len(actual) != 4 or any(type(v) is not bool for v in actual)
                or actual != [i in preferences["flow_heads"] for i in range(4)]):
            raise Blocked("The printer did not confirm the selected calibration toolheads.")


def gcode_command(line):
    return line.split(";", 1)[0].strip().upper()


def select_cover_policy(filaments):
    """Snapmaker GCode.cpp policy over USED filaments, never material-name guesses.

    Source: Snapmaker/OrcaSlicer v2.4.0, GCode.cpp lines 2484-2503.
    Ordinary Orca lacks filament_is_high_temperature: its absent flag is false.
    """
    if not filaments:
        raise Blocked("No used filaments are available for automatic Top Cover setup.")
    threshold = None
    for filament in filaments:
        if filament.get("filament_is_high_temperature") is True:
            continue
        value = filament.get("temperature_vitrification")
        if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
            raise Blocked("Missing softening temperature for filament %d (%s). Re-slice with filament profile metadata." % (filament.get("id", 0) + 1, filament.get("type", "Unknown")))
        threshold = value if threshold is None else min(threshold, value)
    if threshold is not None and threshold <= 50:
        preset = "strong"
    elif threshold is not None and threshold <= 70:
        preset = "weak"
    else:
        preset = "keep-warm"
    return {
        "mode": "Internal Circulation" if preset == "keep-warm" else "External Circulation",
        "command": COVER_COMMANDS[preset],
        "preset": preset,
        "softening_temperature": threshold,
    }


def prepare_job_bytes(original, filaments, preferences, cover_mode, cover_present):
    """Only edit known startup settings, never toolpaths, temperatures or calibration moves."""
    if not isinstance(original, bytes) or len(original) > 256 * 1024 * 1024:
        raise Blocked("G-code exceeds the supported 256 MB setup limit.")
    try:
        text = original.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise Blocked("Only plain UTF-8 G-code is supported.")
    cover_speeds = cover_mode if isinstance(cover_mode, dict) else None
    custom_cover = cover_speeds is not None and "preset" in cover_speeds
    if cover_speeds is not None:
        cover_mode = cover_speeds["preset"] if custom_cover else "auto"
        if custom_cover and cover_mode not in ("strong", "weak", "keep-warm"):
            raise Blocked("Invalid Top Cover preset.")
    if cover_mode not in COVER_MODES:
        raise Blocked("Invalid top cover mode.")
    if cover_present is None and cover_mode != "off":
        raise Blocked("Top cover presence is unknown. Reconnect or choose Off before applying settings.")
    lines = text.splitlines(keepends=True)
    end = next((i for i, line in enumerate(lines) if re.match(r"^;\s*(?:CHANGE_LAYER|LAYER_CHANGE|LAYER:)", line)), len(lines))
    starts = [i for i, line in enumerate(lines) if re.fullmatch(r"PRINT_START(?:\s+[^;]*)?", gcode_command(line))]
    if len(starts) != 1 or starts[0] >= end:
        raise Blocked("A single stock PRINT_START is required. The G-code was not changed.")
    start = starts[0]
    # Match Snapmaker Orca: configure the cover after initial heating/acceleration,
    # immediately before the first homing/motion command. Minimal custom starts
    # without explicit motion retain the original PRINT_START insertion point.
    cover_at = next((i for i in range(start + 1, end)
                     if re.match(r"^(?:G0?0|G0?1|G28)(?:\s|$)", gcode_command(lines[i]))), start + 1)
    # Existing G-code must not reset the task state sent through Moonraker.
    conflicts = ("SET_PRINT_EXTRUDER_MAP", "SET_PRINT_USED_EXTRUDERS", "SET_PRINT_PREFERENCES",
                 "RESET_PRINT_TASK_CONFIG", "LOAD_PRINT_TASK_CONFIG")
    if any(gcode_command(line).split(" ", 1)[0] in conflicts for line in lines):
        raise Blocked("This G-code already overrides print-task settings. Re-slice with a stock U1 start profile.")
    existing = [gcode_command(line) for line in lines[:end] if gcode_command(line).startswith("SET_PURIFIER_MODE ")]
    effective = "off" if cover_present is False else cover_mode
    if effective == "auto":
        command = select_cover_policy(filaments)["command"]
    else:
        command = COVER_COMMANDS[effective]
    if cover_present is False:
        command = None
    if cover_speeds is not None and cover_present is True:
        internal = cover_mode == "keep-warm" if custom_cover else "MODE=3 " in command
        exhaust, inner = cover_speeds.get("exhaust"), cover_speeds.get("inner")
        if (type(exhaust) is not int or type(inner) is not int or
                not 0 <= exhaust <= 100 or not 0 <= inner <= 100 or
                (internal and (exhaust != 0 or inner < 10)) or
                (not internal and exhaust < 1) or
                (inner % 5 != 0) or (exhaust != 1 and exhaust % 5 != 0)):
            raise Blocked("Invalid Top Cover fan settings for the selected circulation mode.")
        command = re.sub(r"FAN_SPEED=[\d.]+", "FAN_SPEED=" + format((inner if internal else exhaust) / 100, ".2f"), command)
        if not internal:
            command += "\n; u1send: recirculation\nSET_PURIFIER FAN=inner SPEED=" + format(inner / 100, ".2f") + " DELAY_OFF=0"
    wait_at = None
    after_preheat = None
    if custom_cover and cover_present is True:
        target, alarm = cover_speeds.get("target"), cover_speeds.get("alarm")
        delay, preheat = cover_speeds.get("delay"), cover_speeds.get("preheat")
        if type(delay) is not int or not 0 <= delay <= 1800 or type(preheat) is not bool:
            raise Blocked("Invalid Top Cover delay or preheat setting.")
        if not internal and (type(target) is not int or not 1 <= target <= 99):
            raise Blocked("Enter a Top Cover target temperature between 1 and 99 °C.")
        if not internal and (type(alarm) is not int or not target + 1 <= alarm <= 100):
            raise Blocked("Top Cover alarm temperature must be at least 1 °C above the target and at most 100 °C.")
        preheat_temp = cover_speeds.get("preheat_temp", target if internal else None)
        if preheat and (type(preheat_temp) is not int or not 1 <= preheat_temp <= 100):
            raise Blocked("Enter a chamber preheat temperature between 1 and 100 °C.")
        if internal:
            target = preheat_temp if preheat else 0
        command = re.sub(r"DESIRE_TEMP=[\d.]+", f"DESIRE_TEMP={target:g}", command)
        if not internal:
            command = re.sub(r"ALARM_TEMP=[\d.]+", f"ALARM_TEMP={alarm:g}", command)
        command = re.sub(r"DELAY_OFF=\d+", f"DELAY_OFF={delay}", command, count=1)
        if preheat:
            bed_wait = next((i for i in range(start + 1, end)
                             if re.match(r"^M190(?:\s|$)", gcode_command(lines[i]))), None)
            if bed_wait is None:
                raise Blocked("Chamber Preheat requires M190 in the start G-code.")
            wait_at = max(cover_at, bed_wait + 1)
            if not internal:
                after_preheat = command
                command = f"SET_PURIFIER_MODE MODE=3 DESIRE_TEMP={preheat_temp} FAN_SPEED=0.60 DELAY_OFF=0"
    newline = "\r\n" if b"\r\n" in original else "\n"
    output = []
    for i, line in enumerate(lines):
        if i == cover_at and command is not None:
            if output and not output[-1].endswith(("\r", "\n")):
                output[-1] += newline
            output.extend(["; u1send: top cover" + newline, command.replace("\n", newline) + newline])
        if i == wait_at:
            output.extend(["; u1send: chamber preheat" + newline, "WAIT_CHAMBER_TEMP TIMEOUT=180" + newline])
            if after_preheat is not None:
                output.append(after_preheat.replace("\n", newline) + newline)
        code = gcode_command(line)
        if i < end:
            if line.strip() in ("; u1send: top cover", "; u1send: chamber preheat", "; u1send: recirculation"):
                continue
            if code.startswith("SET_PURIFIER_MODE "):
                continue
            generated_fan = i > 0 and lines[i - 1].strip() == "; u1send: recirculation"
            if (cover_speeds is not None or generated_fan) and code.startswith("SET_PURIFIER "):
                if not re.fullmatch(r"SET_PURIFIER FAN=INNER SPEED=\d+(?:\.\d+)? DELAY_OFF=0", code):
                    raise Blocked("An existing Top Cover fan override prevents safe setup.")
                continue
            generated_wait = i > 0 and lines[i - 1].strip() == "; u1send: chamber preheat"
            if code.startswith("WAIT_CHAMBER_TEMP") and (
                generated_wait or custom_cover or effective == "off" or "MODE=1 " in (command or "")
            ):
                continue
            for name, flag in (("SET_PRINT_AUTO_BED_LEVELING", preferences["leveling"]),
                               ("SET_TIME_LAPSE_CAMERA", preferences["timelapse"])):
                if code.startswith(name + " "):
                    if not re.fullmatch(name + r"\s+ENABLE=[01]", code):
                        raise Blocked("An unknown startup preference override prevents safe setup.")
                    line = f"{name} ENABLE={int(flag)}" + newline
        output.append(line)
    if cover_at == len(lines) and command is not None:
        if output and not output[-1].endswith(("\r", "\n")):
            output[-1] += newline
        output.extend(["; u1send: top cover" + newline, command.replace("\n", newline) + newline])
    if wait_at == len(lines):
        if output and not output[-1].endswith(("\r", "\n")):
            output[-1] += newline
        output.extend(["; u1send: chamber preheat" + newline, "WAIT_CHAMBER_TEMP TIMEOUT=180" + newline])
        if after_preheat is not None:
            output.append(after_preheat.replace("\n", newline) + newline)
    encoded = "".join(output).encode("utf-8")
    return (b"\xef\xbb\xbf" + encoded if original.startswith(b"\xef\xbb\xbf") else encoded)


class ApplyFailure(Blocked):
    def __init__(self, message, audit):
        super().__init__(message)
        self.audit = list(audit)


def start_native_preview(data, window_box, stop, owner, pending):
    """Export on Orca's UI callback; decode only the active plate on a worker."""
    window = window_box.get("window")
    if not window or stop.is_set() or owner.tearing_down or pending["suspended"]:
        return
    def deliver(pair):
        data["native_preview_pair"] = pair
        data["native_preview_loading"] = False
        current = window_box.get("window")
        if stop.is_set() or owner.tearing_down or pending["suspended"] or not current:
            return
        try:
            if current.is_open():
                current.post({"kind": "native_preview", "pair": pair})
        except Exception:
            # Optional preview must not affect settings, cancellation or sending.
            pass
    if data.get("native_preview_attempted"):
        if not data.get("native_preview_loading"):
            deliver(data.get("native_preview_pair"))
        return
    data["native_preview_attempted"] = True
    data["native_preview_loading"] = True
    folder = None
    def cleanup():
        if folder is not None:
            try:
                folder.cleanup()
            except OSError:
                pass
    try:
        # These host calls must stay on the UI thread. Never move them to decode().
        plater = orca.host.plater()
        plate = orca.host.model().current_plate_index() + 1
        folder = tempfile.TemporaryDirectory(prefix="snapsend-preview-")
        path = os.path.join(folder.name, "preview.3mf")
        if plater.export_3mf_copy(path) is False:
            raise ValueError("Native preview export failed")
    except Exception:
        cleanup()
        deliver(None)
        return
    def decode():
        pair = None
        try:
            if not stop.is_set() and not owner.tearing_down:
                pairs = extract_pairs(path, plate=plate)
                pair = next((item for item in pairs if item["plate"] == plate), None)
        except Exception:
            pass
        finally:
            cleanup()
        deliver(pair)
    try:
        threading.Thread(target=decode, name="snapsend-preview-decode", daemon=True).start()
    except Exception:
        cleanup()
        deliver(None)


def printer_waiting(status):
    return (status.get("raw_state") in {"standby", "complete", "cancelled"}
            and status.get("klippy_ready") is True and status.get("idle") is True)


def encode_preview_png(width, height, pixels):
    def chunk(kind, content):
        return struct.pack('>I', len(content)) + kind + content + struct.pack('>I', zlib.crc32(kind + content) & 0xffffffff)
    stride = width * 4
    rows = b''.join(b'\0' + pixels[y * stride:(y + 1) * stride] for y in range(height))
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 6, 0, 0, 0))
            + chunk(b'IDAT', zlib.compress(rows, 6)) + chunk(b'IEND', b''))


def prepare_job_filament_colors(original, filaments, mapping, heads):
    """Update assigned logical slots in color comments only; preserve every other byte."""
    used = {f.get("id") for f in filaments if type(f.get("id")) is int}
    by_head = {h.get("id"): h.get("color") for h in heads}
    replacements = {}
    for logical, physical in mapping.items():
        try:
            index = int(logical)
        except (ValueError, TypeError):
            continue
        shade = by_head.get(physical)
        if index not in used or index < 0 or not isinstance(shade, str):
            continue
        if re.fullmatch(r"#[0-9a-fA-F]{6}(?:[0-9a-fA-F]{2})?", shade):
            replacements[index] = shade[:7].upper().encode("ascii")
    if not replacements:
        return original, 0
    pattern = re.compile(rb"^(?P<prefix>(?:\xef\xbb\xbf)?;[ \t]*(?:filament_colour|extruder_colour)[ \t]*=[ \t]*)(?P<values>[^\r\n]*)", re.MULTILINE)
    count = 0
    def replace(match):
        nonlocal count
        parts = match["values"].split(b";")
        for index, shade in replacements.items():
            if index >= len(parts):
                continue
            token = parts[index]
            core = token.strip(b" \t")
            quote = core[:1] if core[:1] in (b'"', b"'") and core[-1:] == core[:1] else b""
            old = core[1:-1] if quote else core
            if old and not re.fullmatch(rb"#[0-9a-fA-F]{6}(?:[0-9a-fA-F]{2})?", old):
                continue
            # Preserve alpha if the source encodes it; only RGB is reassigned.
            value = shade + (old[7:9] if len(old) == 9 else b"")
            value = quote + value + quote
            left = len(token) - len(token.lstrip(b" \t"))
            right = max(left, len(token.rstrip(b" \t")))
            updated = token[:left] + value + token[right:]
            if updated != token:
                parts[index] = updated
                count += 1
        return match["prefix"] + b";".join(parts)
    return pattern.sub(replace, original), count


def prepare_job_thumbnail(original, preview, mapping, heads):
    """Replace only PNG comment blocks, tied to the exact displayed assignments/colors."""
    if not isinstance(preview, dict) or preview.get('mapping') != {str(k): v for k, v in mapping.items()}:
        return original, 0
    colors = preview.get('heads')
    if not isinstance(colors, dict) or any(colors.get(str(h['id'])) != h.get('color') for h in heads if h['id'] in mapping.values()):
        return original, 0
    uri = preview.get('png')
    prefix = 'data:image/png;base64,'
    if not isinstance(uri, str) or not uri.startswith(prefix) or len(uri) > 1400000:
        return original, 0
    try:
        raw = base64.b64decode(uri[len(prefix):], validate=True)
        width, height, pixels = png_rgba(raw)
    except (ValueError, struct.error, zlib.error):
        return original, 0
    pattern = re.compile(rb'^;[ \t]*thumbnail begin ([0-9]+)x([0-9]+)[^\r\n]*\r?\n(?:;[^\r\n]*\r?\n)*?;[ \t]*thumbnail end[^\r\n]*(?:\r?\n|$)', re.MULTILINE)
    count = 0
    def replace(match):
        nonlocal count
        w, h = int(match[1]), int(match[2])
        if not (0 < w <= 2048 and 0 < h <= 2048):
            return match[0]
        if (w, h) == (width, height):
            resized = raw
        else:
            out = bytearray(w * h * 4)
            for y in range(h):
                sy = min(height - 1, int((y + .5) * height / h))
                for x in range(w):
                    sx = min(width - 1, int((x + .5) * width / w))
                    src = (sy * width + sx) * 4
                    dst = (y * w + x) * 4
                    out[dst:dst+4] = pixels[src:src+4]
            resized = encode_preview_png(w, h, out)
        if len(resized) > 512 * 1024:
            return match[0]
        encoded = base64.b64encode(resized)
        nl = b'\r\n' if b'\r\n' in match[0] else b'\n'
        trailing = nl if match[0].endswith(b'\n') else b''
        count += 1
        return (b'; thumbnail begin %dx%d %d' % (w, h, len(encoded)) + nl
                + nl.join(b'; ' + encoded[i:i+78] for i in range(0, len(encoded), 78)) + nl
                + b'; thumbnail end' + trailing)
    return pattern.sub(replace, original), count


def apply_job_settings(client, data, mapping, preferences, cover_mode, expected_heads,
                       read_job, write_job, stopped=lambda: False, *, allow_material_mismatch=False, allow_empty_heads=False):
    """Bound to this job. Every mutation requires a freshly confirmed standby state."""
    audit = ["Target: " + client.base if hasattr(client, "base") else "Target: current profile"]
    original = changed = None
    written = attempted = False
    try:
        if data.get("scope") != "plate" or data.get("warning"):
            raise Blocked("A sliced plate with valid used-material metadata is required.")
        if isinstance(cover_mode, dict) and "preset" in cover_mode and data.get("allow_manual_cover") is not True:
            raise Blocked("Enable manual Top Cover settings in SnapSend Settings first.")
        validate_setup(data["filaments"], expected_heads, mapping, preferences, allow_material_mismatch=allow_material_mismatch, allow_empty_heads=allow_empty_heads)
        audit.append("Material validation: explicit user override (material mismatch or empty heads)" if allow_material_mismatch else "Material validation: PASS (loaded heads; exact material types)")
        for logical, physical in sorted(mapping.items(), key=lambda item: int(item[0])):
            audit.append(f"Requested assignment: model {int(logical)+1} -> Head {physical+1} (T{physical})")
        original = read_job()
        before = client.read()
        audit.append("Printer state: " + str(before.get("raw_state", "unknown")))
        if stopped():
            raise Blocked("The setup window was closed. No new settings were sent.")
        if not printer_waiting(before):
            raise Blocked("The printer is not ready for these settings. No settings were sent.")
        if before["heads"] != expected_heads:
            raise HeadsChanged("Loaded filaments changed. Click Refresh and review your assignments.", expected_heads, before["heads"])
        preferences = dict(preferences)
        if "flow_heads" in preferences:
            supported = before["task"].get("flow_calib_extruders")
            if not (isinstance(supported, list) and len(supported) == 4 and all(type(v) is bool for v in supported)):
                if preferences["flow"] and preferences["flow_heads"] != [0, 1, 2, 3]:
                    raise Blocked("This firmware does not report calibration toolhead selection. Select all four heads or disable Dynamic Flow Calibration.")
                preferences.pop("flow_heads")
        script = settings_script(data["filaments"], before["heads"], mapping, preferences, allow_material_mismatch=allow_material_mismatch, allow_empty_heads=allow_empty_heads)
        require_settings_commands(before.get("commands"), script)
        changed = prepare_job_bytes(original, data["filaments"], preferences, cover_mode, before["cover_present"])
        changed, color_count = prepare_job_filament_colors(changed, data["filaments"], mapping, before["heads"]) if data.get("update_job_colors") is not False else (changed, 0)
        audit.append("Job filament colors: %d assigned slot value(s) updated" % color_count)
        changed, preview_count = prepare_job_thumbnail(changed, data.get('job_preview') if data.get('update_job_preview') is not False else None, mapping, before['heads'])
        audit.append('Job thumbnail: %d PNG block(s) updated from displayed preview' % preview_count)
        audit.append("Top cover: requested " + str(cover_mode) + "; detected " + str(before["cover_present"]))
        audit.append("Working G-code preparation: PASS; " + ("startup settings adjusted" if changed != original else "no changes needed"))
        audit.append("Original SHA-256: " + hashlib.sha256(original).hexdigest())
        audit.append("Prepared SHA-256: " + hashlib.sha256(changed).hexdigest())
        cover_lines = [gcode_command(line) for line in changed.decode("utf-8-sig").splitlines()
                       if gcode_command(line).startswith("SET_PURIFIER_MODE ")]
        for command in cover_lines:
            audit.append("Queued in job (not executed now): " + command)
        latest = client.read()
        audit.append("Pre-send state: " + str(latest.get("raw_state", "unknown")))
        if latest["heads"] != before["heads"]:
            raise HeadsChanged("Loaded filaments changed. Click Refresh and review your assignments.", before["heads"], latest["heads"])
        if stopped() or not printer_waiting(latest) or latest["cover_present"] != before["cover_present"]:
            raise Blocked("Printer state changed before applying settings. Nothing was sent.")
        require_settings_commands(latest.get("commands"), script)
        if changed != original:
            write_job(original, changed)
            written = True
            audit.append("Working G-code update: DONE (this upload only)")
        if stopped():
            raise Blocked("The setup window was closed before sending settings.")
        audit.append("POST /printer/gcode/script: sending one settings batch")
        audit.extend("  " + command for command in script.splitlines())
        attempted = True
        client.send_settings(script)
        audit.append("Settings batch: ACKNOWLEDGED by Moonraker")
        confirmed = client.read()
        if confirmed["heads"] != before["heads"]:
            raise HeadsChanged("Loaded filaments changed. Click Refresh and review your assignments.", before["heads"], confirmed["heads"])
        if stopped() or not printer_waiting(confirmed):
            raise Blocked("Printer state changed while verifying settings.")
        verify_task_settings(confirmed["task"], mapping, preferences)
        audit.append("Readback: PASS (extruder_map_table, extruders_used, all three preferences)")
        cover_summary = "Top Cover not detected — skipped." if before["cover_present"] is False else "Top Cover command prepared in this job." if cover_lines else "Top Cover: no command queued."
        audit.append("Result: assignments and preferences CONFIRMED; " + cover_summary)
        audit.append("Upload/start: delegated to OrcaSlicer; SnapSend did not upload or start a print")
        return {"applied": True, "mapping": dict(mapping), "preferences": dict(preferences), "cover_summary": cover_summary, "debug": audit}
    except Exception as exc:
        if written:
            try:
                write_job(changed, original)
                audit.append("Working G-code rollback: DONE")
            except Exception:
                audit.append("Working G-code rollback: FAILED; file state is uncertain")
        audit.append("Failure: " + (str(exc) if isinstance(exc, Blocked) else type(exc).__name__))
        audit.append("Settings POST: " + ("ATTEMPTED; result may be partial/unknown" if attempted else "NOT SENT"))
        audit.append("No automatic retry. No print-start request. No Pipeline error.")
        message = ("Settings could not be confirmed. Some may already be applied; no automatic retry. "
                   "OrcaSlicer will continue after you choose Continue.") if attempted else str(exc)
        failure = ApplyFailure(message, audit)
        failure.heads_changed = isinstance(exc, HeadsChanged)
        failure.changes = getattr(exc, "changes", "")
        raise failure from None


def prepare_cancel_job(original, missing_materials, heads_changed=False):
    """Insert a verified U1 file-cancellation guard before any executable line."""
    names = sorted({material(name) for name in missing_materials})
    if not names or any(not re.fullmatch(r"[A-Z0-9][A-Z0-9 _+./-]{0,47}", name) for name in names):
        raise Blocked("Missing-material names are invalid. File was not changed.")
    try:
        text = original.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise Blocked("Only plain UTF-8 G-code supports a cancellation guard.") from None
    marker = "; SnapSend: unavailable material cancellation guard"
    if marker in text:
        raise Blocked("This file already has a cancellation guard. Re-slice and send a new file.")
    nl = "\r\n" if "\r\n" in text else "\n"
    lines = text.splitlines(keepends=True)
    first = next((i for i, line in enumerate(lines) if line.strip() and not line.lstrip().startswith(";")), None)
    if first is None:
        raise Blocked("No executable G-code found. File was not changed.")
    commands = [marker,
                "M118 [SnapSend] ERROR: Required filament " + ", ".join(names) + " is unavailable.",
                "M118 [SnapSend] No compatible toolhead is assigned. Printing will be cancelled.",
                "M118 [SnapSend] This file will always cancel printing. Do not reuse it.",
                "M118 [SnapSend] Load the required filament, re-slice the model and send a new file.",
                "CANCEL_PRINT", "; SnapSend: end cancellation guard"]
    if heads_changed:
        commands[1] = "M118 [SnapSend] ERROR: Loaded material or color changed for " + ", ".join(names) + "."
        commands[2] = "M118 [SnapSend] Toolhead assignments were not revalidated. Printing will be cancelled."
    prepared = "".join(lines[:first]) + nl.join(commands) + nl + "".join(lines[first:])
    return (b"\xef\xbb\xbf" if original.startswith(b"\xef\xbb\xbf") else b"") + prepared.encode("utf-8")



