def prepare_user_cancel_job(original):
    """Cancel only the working upload copy, at the user's explicit request."""
    if b"; SnapSend: user-requested cancellation guard" in original:
        raise Blocked("This file already has a cancellation guard. Re-slice and send a new file.")
    prepared = prepare_cancel_job(original, ["USER REQUEST"])
    replacements = {
        b"; SnapSend: unavailable material cancellation guard": b"; SnapSend: user-requested cancellation guard",
        b"M118 [SnapSend] ERROR: Required filament USER REQUEST is unavailable.": b"M118 [SnapSend] Printing cancelled at the user's request.",
        b"M118 [SnapSend] No compatible toolhead is assigned. Printing will be cancelled.": b"M118 [SnapSend] Setup was closed without applying settings.",
        b"M118 [SnapSend] Load the required filament, re-slice the model and send a new file.": b"M118 [SnapSend] Re-slice and send a new file to print.",
    }
    for before, after in replacements.items():
        prepared = prepared.replace(before, after)
    return prepared


def unapplied_notice_html(language="en", theme="auto"):
    copy = UNAPPLIED_NOTICE_COPY.get(language, UNAPPLIED_NOTICE_COPY["en"])
    page = UNAPPLIED_NOTICE_TEMPLATE
    for name, value in copy.items():
        page = page.replace("@@" + name + "@@", value)
    return page.replace("@@LANG@@", language).replace("@@THEME@@", theme)


def close_warning_html(heads_changed=False, missing_materials=(), cancel_override=False, close_notice=False, language="en", theme="auto", legacy_rows=None):
    if close_notice:
        return unapplied_notice_html(language, theme)
    # Both entry paths render the exact same warning component and behavior.
    return page_html({"project": "", "address": "", "filaments": [], "preferences": DEFAULT_PREFS,
                      "native_warning": True, "native_missing": list(missing_materials), "legacy_rows": legacy_rows,
                      "heads_changed": heads_changed, "cancel_override": cancel_override, "close_notice": close_notice, "language": language, "theme": theme})


def job_io(path):
    """Open only the working G-code path supplied by the Orca Pipeline context."""
    def read():
        if os.path.getsize(path) > 256 * 1024 * 1024:
            raise Blocked("G-code exceeds the supported 256 MB setup limit.")
        with open(path, "rb") as stream:
            return stream.read()
    def replace(expected, replacement):
        with open(path, "r+b") as stream:
            if stream.read() != expected:
                raise Blocked("The working G-code changed. Setup was skipped.")
            try:
                stream.seek(0)
                stream.write(replacement)
                stream.truncate()
                stream.flush()
            except Exception:
                stream.seek(0)
                stream.write(expected)
                stream.truncate()
                stream.flush()
                raise
    return read, replace


