ing #note{width:100%;margin:14px 0 0;flex-shrink:0}\n.onboarding button{margin:22px auto 0;flex-shrink:0}\n.onboarding #saved{margin-top:8px;min-height:0}\n.onboarding #saved:empty{display:none}\n\nhtml,body{background:transparent}\nbody:not(.onboarding) #big-globe{display:none}\nbody.onboarding #small-globe{display:none}\n</style><body><svg class="globe big-globe" id="big-globe" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 7h14M5 17h14"/></svg><h1 id="heading"></h1>\n<h2 class="settings-section" id="appearance-section"></h2><label class="language" for="language"><svg class="globe" id="small-globe" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 7h14M5 17h14"/></svg>Language / Язык</label>\n<select id="language"><option value="en">English</option><option value="zh-CN">简体中文</option><option value="ru">Русский</option><option value="es">Español</option><option value="ja">日本語</option></select><p id="note"></p>\n<label class="theme-row tab-option"><input id="show-snapsend-tab" type="checkbox" checked><span id="show-tab-title"></span></label><label class="theme-row auto-pipeline-row"><input id="auto-pipeline-setting" class="theme-check" type="checkbox"><span id="auto-pipeline-title"></span></label><div id="advanced"><h2 class="settings-section" id="post-placeholder" hidden></h2><div id="preview-option"><label><input id="update-preview" type="checkbox" checked><span id="update-preview-title"></span></label></div><p class="option-hint" id="preview-hint"></p><h2 class="settings-section" id="post-section"></h2><div id="colors-option" class="extended-option"><label><input type="checkbox" id="update-colors"><span id="update-colors-title"></span></label><p class="option-hint" id="colors-hint"></p></div><h2 class="settings-section" id="expert-section"></h2><div class="extended-option"><label><input type="checkbox" id="allow-mismatch"><span id="mismatch-title"></span></label><p class="option-hint" id="mismatch-hint"></p></div><div class="extended-option"><label><input type="checkbox" id="allow-empty"><span id="empty-title"></span></label><p class="option-hint" id="empty-hint"></p></div><div class="extended-option"><label><input type="checkbox" id="allow-manual-cover"><span id="manual-cover-title"></span></label></div><span id="advanced-title" hidden></span><input id="debug" type="checkbox" hidden><span id="debug-title" hidden></span><p id="hint" hidden></p></div>\n<button id="save"></button><div id="saved" role="status"></div><div class="legal" id="legal"><span id="license"></span>: <a href="https://www.gnu.org/licenses/gpl-3.0.html">GPL-3.0-only</a><br><span id="contact"></span>: <a href="mailto:ilya.vlasievsky@yandex.ru">ilya.vlasievsky@yandex.ru</a></div>\n<script>\nconst extraInitial=__EXTENDED_OPTIONS__;const initial=__INITIAL__,labels=__LABELS__,$=id=>document.getElementById(id),onboarding=initial.onboarding;\n$(\'show-snapsend-tab\').checked=extraInitial.show_snapsend_tab!==false;$(\'tab-placeholder\')?.remove();$(\'auto-pipeline-setting\').checked=extraInitial.auto_pipeline===true;$(\'update-colors\').checked=extraInitial.update_job_colors!==false;$(\'allow-mismatch\').checked=extraInitial.allow_material_mismatch!==true;$(\'allow-empty\').checked=extraInitial.allow_empty_heads!==true;$(\'allow-manual-cover\').checked=extraInitial.allow_manual_cover!==true;$(\'language\').value=initial.language;$(\'debug\').checked=false;$(\'update-preview\').checked=__UPDATE_JOB_PREVIEW__;document.body.classList.toggle(\'onboarding\',onboarding);\n$(\'big-globe\').toggleAttribute(\'hidden\',!onboarding);$(\'small-globe\').toggleAttribute(\'hidden\',onboarding);$(\'advanced\').hidden=onboarding;$(\'legal\').hidden=onboarding;$(\'note\').hidden=!onboarding;\nfunction render(){const t=labels[$(\'language\').value];$(\'update-preview-title\').textContent={"en": "Update preview in G-code file", "ru": "\\u041e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0442\\u044c \\u043f\\u0440\\u0435\\u0432\\u044c\\u044e \\u0432 G-code \\u0444\\u0430\\u0439\\u043b\\u0435", "es": "Actualizar vista previa en el archivo", "zh-CN": "\\u66f4\\u65b0\\u6587\\u4ef6\\u4e2d\\u7684\\u9884\\u89c8", "ja": "\\u30d5\\u30a1\\u30a4\\u30eb\\u5185\\u306e\\u30d7\\u30ec\\u30d3\\u30e5\\u30fc\\u3092\\u66f4\\u65b0"}[$(\'language\').value];document.documentElement.lang=$(\'language\').value;$(\'heading\').textContent=onboarding?({en:\'Initial Setup\',ru:\'Стартовые настройки\',es:\'Configuración inicial\',\'zh-CN\':\'初始设置\',ja:\'初期設定\'}[$(\'language\').value]):\'SnapSend · \'+t.settings;$(\'note\').textContent=t.note;$(\'advanced-title\').textContent=t.advanced;$(\'debug-title\').textContent=t.debug;$(\'hint\').textContent=t.hint;$(\'save\').textContent=t.save;$(\'license\').textContent=t.license;$(\'contact\').textContent=t.contact;$(\'saved\').textContent=\'\'}\n$(\'language\').onchange=render;\nwindow.orca.onMessage(data=>{if(data.kind===\'saved\'){$(\'saved\').textContent=labels[$(\'language\').value].saved}else if(data.kind===\'error\'){$(\'saved\').textContent=labels[$(\'language\').value].error;$(\'saved\').style.color=\'#b43e36\'}$(\'save\').disabled=false});\n$(\'save\').onclick=()=>{$(\'save\').disabled=true;window.orca.postMessage({action:\'save_language\',language:$(\'language\').value,debug_mode:$(\'debug\').checked,update_job_preview:$(\'update-preview\').checked,update_job_colors:$(\'update-colors\').checked,allow_material_mismatch:!$(\'allow-mismatch\').checked,allow_empty_heads:!$(\'allow-empty\').checked,allow_manual_cover:!$(\'allow-manual-cover\').checked,auto_pipeline:$(\'auto-pipeline-setting\').checked,show_snapsend_tab:$(\'show-snapsend-tab\').checked})};render();\n</script><style>\n#note,#hint,#saved,.legal,#ss-versions{font-size:12px!important}\nbutton{font-size:15px!important}\n.settings-footer button{font-size:12px!important}\n</style><style>\nbody{font-size:15px}\nselect,label.language,.theme-row,summary{font-size:15px}\n#note,#hint,#saved,#ss-versions{font-size:12px!important}\n#save{min-height:42px!important;height:auto!important;padding:10px 20px!important;border-radius:10px!important;box-sizing:border-box!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:7px!important;font-size:15px!important;line-height:20px!important;text-align:center!important;white-space:normal!important}\n.settings-footer{display:grid!important;grid-auto-flow:column;grid-auto-columns:1fr;justify-content:center!important;align-items:stretch!important;gap:12px!important;width:max-content;max-width:100%;margin:23px auto 0!important}\n.settings-footer button{min-height:42px!important;height:auto!important;padding:10px 20px!important;border-radius:10px!important;box-sizing:border-box!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:7px!important;font-size:15px!important;line-height:20px!important;text-align:center!important;white-space:normal!important;width:auto!important;min-width:120px!important;max-width:100%;margin:0!important}\n.settings-footer button[hidden],#save[hidden]{display:none!important}\n.snap-select{min-width:0;max-width:100%;box-sizing:border-box}\n.snap-select-trigger{width:100%!important;height:42px!important;min-height:42px!important;padding:8px 12px!important;display:flex!important;justify-content:space-between!important;text-align:left!important;font-size:15px!important}\n.snap-select-menu{box-sizing:border-box;min-width:0!important;width:100%;max-width:100%;left:0;right:0;max-height:240px;overflow-y:auto}\n.snap-select-menu button{width:100%!important;min-height:36px!important;height:auto!important;padding:8px 12px!important;display:block!important;text-align:left!important;font-size:15px!important;line-height:20px!important;white-space:nowrap!importan