def settings_html(language="en", debug_mode=False, onboarding=False):
    data={"language":language,"debug_mode":debug_mode,"onboarding":onboarding}
    return SETTINGS_PAGE.replace("__INITIAL__",json.dumps(data)).replace("__LABELS__",json.dumps(SETTINGS_LABELS,ensure_ascii=True))


def cancellation_message(language):
    translations = {"ru": "Отправка отменена.", "es": "Envío cancelado.", "zh-CN": "上传已取消。", "ja": "アップロードをキャンセルしました。"}
    translated = translations.get(language)
    return "SnapSend: Upload cancelled." + (" (" + translated + ")" if translated else "")


def missing_assignment_rows(filaments, heads, mapping):
    mapping = mapping if isinstance(mapping, dict) else {}
    effective = native_fallback_mapping(filaments, heads, mapping)
    by_id = {h["id"]: h for h in heads}
    rows = []
    for f in filaments:
        assigned = by_id.get(mapping.get(str(f["id"])))
        if assigned and compatible(f, assigned):
            continue
        target = effective[str(f["id"])]
        if target not in by_id:
            raise Blocked("Toolhead information unavailable.")
        rows.append({"type": f["type"], "logical": f["id"], "head": target, "material": by_id[target]["type"]})
    return rows


def settings_versions_footer(page, version, corner=False):
    labels = {"en":"OrcaSlicer version", "ru":"Версия OrcaSlicer", "es":"Versión de OrcaSlicer", "zh-CN":"OrcaSlicer 版本", "ja":"OrcaSlicer バージョン"}
    from html import escape
    align = "right" if corner else "center"
    footer = '<div id="ss-versions" style="text-align:'+align+';font-size:11px;line-height:16px;color:var(--snap-muted,#718091);margin-top:4px"><div id="ss-orca-version"></div><div id="plugin-version">SnapSend '+escape(PLUGIN_VERSION)+'</div></div>'
    script = '<script>(()=>{const labels='+json.dumps(labels,ensure_ascii=False)+';const version='+json.dumps(str(version or "—"))+';const select=document.getElementById("language");function update(){document.getElementById("ss-orca-version").textContent=(labels[select.value]||labels.en)+": "+version}select.addEventListener("change",update);update()})()</script>'
    return page.replace('</body>',footer+script+'</body>')

def settings_config_html(self):
    promote_native_settings(self)
    self.request_settings_sync()
    config=read_native_config(self)
    language=config.get("language") if config.get("language") in SETTINGS_LABELS else "en"
    page=theme_settings(language,load_theme(self),False,update_preview=config.get("update_job_preview") is not False,options=config)
    try:
        info=orca.host.app_info()
        version=info.get("version", "") if isinstance(info,dict) else getattr(info,"version", "")
    except Exception:
        version=""
    page=settings_versions_footer(page,version)
    # Native Process plugins: place the version lines directly after Contact.
    versions = re.search(r'<div id="ss-versions"[^>]*><div id="ss-orca-version"></div><div id="plugin-version">[^<]*</div></div>', page)
    if versions:
        page = page.replace(versions.group(0), '', 1)
        page = page.replace('ilya.vlasievsky@yandex.ru</a></div>', 'ilya.vlasievsky@yandex.ru</a>'+versions.group(0)+'</div>', 1)
    page = page.replace('<body', '<body data-native-settings', 1)
    target=self.pipeline_snapshot()
    adapter="""<script>
const settingsHost=window.orca;
const pipelineTarget=__PIPELINE_TARGET__;
let settingsReceive=null,pendingConfig=null;
let displayedRevision=__SHARED_REVISION__,nativeDisplay=null;
const configKeys=['language','theme','auto_pipeline','update_job_preview','update_job_colors','allow_material_mismatch','allow_empty_heads','allow_manual_cover','pending_pipeline_removal','settings_revision'];
window.orca={onMessage:fn=>settingsReceive=fn,postMessage:data=>{
 if(data.action!=='save_language')return;
 try{
  let config=settingsHost.getConfig();if(typeof config==='string')config=JSON.parse(config);
  if(!config||typeof config!=='object'||Array.isArray(config))config={};
  const updated={...config,language:data.language,theme:data.theme,debug_mode:false,auto_pipeline:data.auto_pipeline===true,update_job_preview:data.update_job_preview!==false,update_job_colors:data.update_job_colors!==false,allow_material_mismatch:data.allow_material_mismatch===true,allow_empty_heads:data.allow_empty_heads===true,allow_manual_cover:data.allow_manual_cover===true};
  if(!updated.auto_pipeline&&data.remove_auto_pipeline===true&&pipelineTarget)updated.pending_pipeline_removal=pipelineTarget;
  else if(updated.auto_pipeline)updated.pending_pipeline_removal=null;
  updated.settings_revision=Math.max(Date.now(),(Number(config.settings_revision)||0)+1,__SHARED_REVISION__+1);
  pendingConfig=updated;
  const result=settingsHost.saveConfig(updated);
  if(result===false)throw Error('Save failed');
 }catch{pendingConfig=null;settingsReceive?.({kind:'error'})}
}};
function displayNativeSettings(){
 if(!nativeDisplay||document.readyState==='loading')return;
 const config=nativeDisplay;nativeDisplay=null;
 const revision=Number(config.settings_revision)||0;
 if(revision<displayedRevision)return;
 displayedRevision=revision;
 const checkboxValues={'auto-pipeline-setting':config.auto_pipeline===true,'update-preview':config.update_job_preview!==false,'update-colors':config.update_job_colors!==false,'allow-mismatch':config.allow_material_mismatch!==true,'allow-empty':config.allow_empty_heads!==true,'allow-manual-cover':config.allow_manual_cover!==true,'show-snapsend-tab':config.show_snapsend_tab!==false};
 for(const [id,checked] of Object.entries(checkboxValues)){const field=document.getElementById(id);if(field)field.checked=checked;}
 const language=document.getElementById('language'),theme=document.getElementById('theme');
 if(config.language&&[...language.options].some(option=>option.value===config.language))language.value=config.language;
 if(config.theme==='light'||config.theme==='dark')theme.checked=config.theme==='dark';
 language.dispatchEvent(new Event('change',{bubbles:true}));
 theme.dispatchEvent(new Event('change',{bubbles:true}));
 window.snapAutoPipelineSaved?.({});
}
addEventListener('DOMContentLoaded',displayNativeSettings);
settingsHost.onConfig(config=>{
 if(typeof config==='string'){try{config=JSON.parse(config)}catch{return}}
 if(!config)return;
 if(!pendingConfig){nativeDisplay=config;displayNativeSettings();return;}
 if(!configKeys.every(k=>JSON.stringify(config[k])===JSON.stringify(pendingConfig[k])))return;
 displayedRevision=Number(config.settings_revision)||displayedRevision;
 pendingConfig=null;
 settingsReceive?.({kind:'saved',pipeline_present:__PIPELINE_PRESENT__});
});
</script>"""
    adapter=adapter.replace('__SHARED_REVISION__', str(settings_revision(config)))
    adapter=adapter.replace('__PIPELINE_TARGET__',json.dumps(list(target[:2]) if target else None)).replace('__PIPELINE_PRESENT__',json.dumps(current_pipeline_contains_snapsend()))
    page=page.replace('<script>',adapter+'<script>',1)
    page=page.replace('</body>', '<style>body{overflow-y:auto!important}body[data-native-settings] #legal #ss-versions{display:block!important;text-align:left!important;margin:0!important;font:inherit!important;color:#718091!important;line-height:inherit!important}html[data-snap-theme="dark"] body[data-native-settings] #legal #ss-versions{color:#a5b5c0!important}body button#save{margin:24px auto 0}body #saved{position:static!important;margin:10px 0 0!important;text-align:center;min-height:18px}body .legal{margin-top:22px}</style></body>')
    self.request_pipeline_sync()
    return page

def load_theme(owner):
    try:
        value=read_native_config(owner).get("theme")
        return value if value in {"auto","light","dark"} else "auto"
    except (AttributeError,ValueError,TypeError,RuntimeError):
        return "auto"


def load_language(owner):
    try:
        value=read_native_config(owner).get("language")
        return value if value in SETTINGS_LABELS else "en"
    except (AttributeError,ValueError,TypeError,RuntimeError):
        return "en"


INITIAL_SETUP_LABELS = {"en":"Initial Setup","ru":"Стартовые настройки","es":"Configuración inicial","zh-CN":"初始设置","ja":"初期設定"}

def show_install_language(owner):
    try:
        marker=Path(__file__).resolve().with_name(".snapsend-language-shown")
        if marker.exists():return
        config=read_native_config(owner)
        config.setdefault("auto_pipeline", owner.auto_pipeline_enabled())
        holder={}
        def message(data):
            if not isinstance(data,dict) or data.get("action")!="save_language" or data.get("language") not in SETTINGS_LABELS:return
            try:
                updated=dict(read_native_config(owner),language=data["language"],auto_pipeline=data.get("auto_pipeline") is True)
                if data.get("theme") in {"light","dark"}:updated["theme"]=data["theme"]
                # The initial language picker does not change an existing debug preference.
                if owner.save_config(json.dumps(updated)) is False:raise ValueError("Save failed")
                if updated["auto_pipeline"]:
                    owner.update_pipeline(owner.pipeline_snapshot(), automatic=True)
                holder["window"].close()
                owner._language_window = None
            except (AttributeError,ValueError,TypeError,RuntimeError):
                holder["window"].post({"kind":"error"})
        win=orca.host.ui.create_window(html=theme_settings(load_language(owner),load_theme(owner),config.get("debug_mode") is True,onboarding=True, options=config),
                                     title="SnapSend",width=444,height=483,on_message=message)
        holder["window"]=win
        owner._language_window=win
        marker.write_text("Language selection shown for this installation.\n",encoding="utf-8")
    except Exception as exc:
        print("SnapSend: automatic language selection unavailable; use plugin settings:",exc)



