_theme_settings_shared_title_base = theme_settings

def theme_settings(language, theme, debug_mode=False, *, onboarding=False, update_preview=True):
    page = _theme_settings_shared_title_base(language, theme, debug_mode, onboarding=onboarding)
    page = page.replace('__UPDATE_JOB_PREVIEW__', 'true' if update_preview else 'false')
    page = page.replace('</body>', PREVIEW_OPTION_CSS + '</body>')
    if not onboarding:
        page = page.replace('</body>', SETTINGS_SHARED_TITLE_CSS + '</body>')
    return page


SHARED_BACK_BUTTON_CSS = '<style id="snapsend-back-from-print-preferences">\n:is(#settings-back,#ss-heads-v2 .ss-back,#debug-back,#connection-dismiss){font:400 15px/20px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif!important;font-synthesis:none!important;-webkit-font-smoothing:auto!important;color:var(--ss-green-text,light-dark(#568075,#a4c9bc))!important;background:var(--ss-panel,light-dark(#fff,#303e46))!important;border:1px solid var(--ss-line,light-dark(#dce5eb,#46535d))!important;border-radius:10px!important;min-width:120px!important;width:auto!important;height:44px!important;min-height:44px!important;padding:10px 20px!important;box-sizing:border-box!important;line-height:20px!important;white-space:pre!important;text-align:center!important;transform:none!important;gap:7px!important;transition:background .12s,border-color .12s!important}\n:is(#settings-back,#ss-heads-v2 .ss-back,#debug-back,#connection-dismiss):hover{background:var(--ss-hover,light-dark(#eef8f4,#365449))!important;border-color:var(--ss-green,light-dark(#159e80,#22b99b))!important}\n:is(#settings-back,#ss-heads-v2 .ss-back,#debug-back,#connection-dismiss)>span{font:inherit!important;position:static!important;top:auto!important}\n</style><script>(()=>{\nconst selector=\'#settings-back,#ss-heads-v2 .ss-back,#debug-back,#connection-dismiss\';\nfunction arrows(){document.querySelectorAll(selector).forEach(button=>{if(!button.textContent.trim()||button.textContent.trimStart().startsWith(\'←\'))return;button.insertBefore(document.createTextNode(\'← \'),button.firstChild)})}\narrows();new MutationObserver(arrows).observe(document.body,{childList:true,subtree:true,characterData:true});\n})();</script>'
