def page_html(data):
    language=data.get("language","en")
    theme=data.get("theme","auto")
    data = dict(data, protection_copy=PROTECTION_TRANSLATED.get(language,PROTECTION_COPY))
    data["native_material_copy"] = {'en': {'title': 'Required filament unavailable', 'intro': 'No compatible toolheads are assigned for some filaments.', 'auto': 'The toolheads automatically assigned by OrcaSlicer will be used:', 'back': 'Return to SnapSend', 'send': 'Continue anyway', 'head': 'Head', 'blocked': 'Return to SnapSend and assign a loaded head for every filament.', 'noFilament': 'Empty'}, 'ru': {'title': 'Нужный материал отсутствует', 'intro': 'Для некоторых филаментов не назначены совместимые Головы.', 'auto': 'Будут использованы Головы, назначенные OrcaSlicer автоматически:', 'back': 'Вернуться в SnapSend', 'send': 'Всё равно продолжить', 'head': 'Голова', 'blocked': 'Вернитесь в SnapSend и назначьте загруженную Голову для каждого филамента.', 'noFilament': 'Пусто'}, 'es': {'title': 'Falta el filamento necesario', 'intro': 'No se han asignado cabezales compatibles para algunos filamentos.', 'auto': 'Se utilizarán los cabezales asignados automáticamente por OrcaSlicer:', 'back': 'Volver a SnapSend', 'send': 'Continuar de todos modos', 'head': 'Cabezal', 'blocked': 'Vuelva a SnapSend y asigne un cabezal cargado a cada filamento.', 'noFilament': 'Vacío'}, 'zh-CN': {'title': '缺少所需耗材', 'intro': '部分耗材尚未分配兼容的打印头。', 'auto': '将使用 OrcaSlicer 自动分配的打印头：', 'back': '返回 SnapSend', 'send': '仍然继续', 'head': '打印头', 'blocked': '请返回 SnapSend，为每种耗材分配已加载耗材的打印头。', 'noFilament': '空'}, 'ja': {'title': '必要なフィラメントがありません', 'intro': '一部のフィラメントに対応するヘッドが割り当てられていません。', 'auto': 'OrcaSlicer が自動的に割り当てたヘッドが使用されます：', 'back': 'SnapSend に戻る', 'send': 'このまま続行', 'head': 'ヘッド', 'blocked': 'SnapSend に戻り、各フィラメントにロード済みのヘッドを割り当ててください。', 'noFilament': '空'}}
    # Large previews arrive with the existing initial status response, below.
    data['thumbnail'] = None
    data.pop('job_preview', None)
    data.pop('native_preview_pair', None)
    data.pop('native_preview_attempted', None)
    try:
        data["cover_policy"] = select_cover_policy(data.get("filaments", []))
    except Blocked as error:
        data["cover_policy"] = {"error": str(error)}
    # JSON stays data even if a profile name contains HTML/script terminators.
    encoded = json.dumps(data, ensure_ascii=True).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    page = (embedded_workspace_html(PAGE) if data.get("embedded_workspace") else PAGE).replace("__DATA__", encoded)
    page=page.replace('</body>', SHARED_BACK_BUTTON_CSS + '</body>')
    page=page.replace('__PREVIEW_SHARED_UI__', preview_shared_ui_css(aux_pages(data)['extra']))
    page=page.replace(SHARED_BACK_BUTTON_CSS, '')
    page=page.replace('</body>', SHARED_BACK_BUTTON_CSS + '</body>')
    page=page.replace("__AUX_PAGES__",json.dumps({key:value for key,value in aux_pages(data).items() if key != 'heads'},ensure_ascii=True).replace("<","\\u003c"))
    page=page.replace("__SETTINGS_HTML__",json.dumps(main_settings_html(data),ensure_ascii=True).replace("<","\\u003c"))
    review_css="<style>.connection-line{transform:translateY(-3px)}#reconnect{transform:translateY(-9px)}#stats,#detail{position:relative;top:4px}#printing-warning.critical section{max-width:634px;padding-top:30px;padding-bottom:30px}#printing-warning.critical .warning-paragraph+.warning-paragraph{margin-top:16px}</style>"
    if language == "es":
        review_css+="<style>#refresh,#auto-map{width:166px;min-width:166px;white-space:nowrap}</style>"
    page=page.replace("</style><body>","</style>"+review_css+"<body>")
    if language != "en":
        width={"ru":160,"es":154,"ja":142,"zh-CN":142}.get(language,142)
        style="<style>#reconnect{width:"+str(width)+"px;min-width:"+str(width)+"px}</style>"
        page=page.replace("<body>",style+"<body>",1)
    translation=TRANSLATOR.replace("__LANGUAGE__",json.dumps(language)).replace("__DICTIONARY__",json.dumps(TRANSLATIONS.get(language,{}),ensure_ascii=True)).replace("__UNITS__",json.dumps(DYNAMIC_UNITS.get(language,{}),ensure_ascii=True))
    return themed(page.replace("</body>","<script>"+translation+"</script></body>"),theme)


def capture_profile():
    bundle = orca.host.preset_bundle()
    preset = bundle.current_printer_preset()
    def value(key):
        own = preset.config_value(key)
        return own if own is not None else bundle.full_config_value(key)
    identity = str(value("printer_model") or "") + " " + preset.name
    if not re.search(r"\bU1\b", identity, re.I):
        raise Blocked("Select your Snapmaker U1 printer profile before opening the preview.")
    address = str(value("print_host") or "").strip()
    port = str(value("printhost_port") or "").strip()
    if address and port:
        parsed = urllib.parse.urlsplit(address if "://" in address else "http://" + address)
        if parsed.port is None:
            address = urllib.parse.urlunsplit((parsed.scheme, parsed.netloc + ":" + port, parsed.path, parsed.query, parsed.fragment))
    types = profile_values(bundle.full_config_value("filament_type"))
    presets = profile_values(bundle.full_config_value("filament_settings_id"))
    vendors = profile_values(bundle.full_config_value("filament_vendor"))
    colors = profile_values(bundle.full_config_value("filament_colour"))
    filaments = [{"id": i, **project_filament(kind, presets, vendors, i), "color": color(colors[i] if i < len(colors) else None)}
                 for i, kind in enumerate(types)]
    return {"address": address, "project": preset.name, "filaments": filaments, "scope": "profile"}, str(value("printhost_apikey") or "")



def main_settings_html(data):
    page=theme_settings(data.get("language","en"),data.get("theme","auto"),False,update_preview=data.get("update_job_preview") is not False, options=data)
    bridge="""<script>
let settingsReceiver=null;
window.orca={onMessage:fn=>settingsReceiver=fn,postMessage:data=>parent.postMessage({...data,channel:'snapsend-settings'},'*')};
window.addEventListener('message',event=>{if(event.source===parent&&event.data?.channel==='snapsend-settings-result')settingsReceiver?.(event.data)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();parent.postMessage({channel:'snapsend-settings',action:'close'},'*')}});
</script>"""
    return page.replace('<script>',bridge+'<script>',1)


def save_main_plugin_settings(owner, data, message):
    language=message.get("language")
    theme=message.get("theme")
    if language not in SETTINGS_LABELS or theme not in {"light","dark"}:
        raise ValueError("Invalid settings")
    updated=dict(read_native_config(owner),language=language,theme=theme,debug_mode=False,update_job_preview=message.get("update_job_preview") is not False, update_job_colors=message.get("update_job_colors") is not False, allow_material_mismatch=message.get("allow_material_mismatch") is True, allow_empty_heads=message.get("allow_empty_heads") is True, allow_manual_cover=message.get("allow_manual_cover") is True, auto_pipeline=message.get("auto_pipeline") is True, show_snapsend_tab=message.get("show_snapsend_tab") is not False)
    if owner is SETTINGS_OWNER:
        snapshot = owner.pipeline_snapshot()
        remove = not updated["auto_pipeline"] and message.get("remove_auto_pipeline") is True
        if remove and snapshot:
            updated["pending_pipeline_removal"] = list(snapshot[:2])
        elif updated["auto_pipeline"]:
            updated["pending_pipeline_removal"] = None
    if owner.save_config(json.dumps(updated)) is False:
        raise ValueError("Save failed")
    if owner is SETTINGS_OWNER:
        owner.apply_automatic_pipeline()
    else:
        sync_auto_pipeline(updated["auto_pipeline"])
    data.update(language=language,theme=theme,debug_mode=False,update_job_preview=updated["update_job_preview"], **{k:updated[k] for k in EXTENDED_KEYS})
    return {"kind":"main_settings_saved","theme":theme,"language":language,"debug_mode":updated["debug_mode"],"pages":aux_pages(data),"settings_html":main_settings_html(data),"pipeline_present":current_pipeline_contains_snapsend(), **{k:updated[k] for k in EXTENDED_KEYS}}


