def aux_pages(data):
    pages=AUX_PAGES.get(data.get('language'),AUX_PAGES['en'])
    theme=data.get('theme','auto')
    result={}
    for key,page in pages.items():
        patch='<style>html[data-snap-theme="dark"] #ss-head-editor{color-scheme:dark}html[data-snap-theme="dark"] #ss-options-preview{color:#dce5eb}html[data-snap-theme="dark"] #ss-options-preview .window{background:#20262b}html[data-snap-theme="dark"] #ss-options-preview h2,html[data-snap-theme="dark"] #ss-options-preview label{color:#dce5eb}html[data-snap-theme="dark"] #ss-options-preview select{background:#303e46;color:#dce5eb;border-color:#52675f}html[data-snap-theme="dark"] #ss-options-preview .cancel{background:#303e46;color:#a4c9bc;border-color:#52675f}html[data-snap-theme="dark"] #ss-options-preview input[type=checkbox]:not(:checked){background:#303e46}</style>'
        result[key]=themed(page.replace('</body>',patch+'</body>'),theme)
    return result

