_main_settings_original=main_settings_html
def main_settings_html(data):
    page=_main_settings_original(data)
    page=re.sub(r'<div class="legal" id="legal">[\s\S]*?</div>','',page)
    page=page.replace("$('legal').hidden=onboarding;",'')
    page=page.replace("$('license').textContent=t.license;$('contact').textContent=t.contact;",'')
    return page.replace('</body>','<style>'+PLUGIN_REVIEW_CSS+'</style><script>'+PLUGIN_REVIEW_JS+'</script></body>')

SETTINGS_OWNER = None
AUTO_PIPELINE_PAGE = None

def sync_auto_pipeline(enabled):
    if enabled and SETTINGS_OWNER is not None:
        SETTINGS_OWNER.apply_automatic_pipeline()





