_aux_pages_previous = aux_pages
def aux_pages(data):
    pages = _aux_pages_previous(data)
    language = data.get('language','en')
    theme = data.get('theme','light')
    if theme not in ('light','dark'): theme = 'light'
    pages['heads'] = HEADS_V2_PAGES.get(language+'-'+theme,HEADS_V2_PAGES['en-'+theme])
    for resolved in ('light','dark'):
        pages['heads_'+resolved] = HEADS_V2_PAGES.get(language+'-'+resolved,HEADS_V2_PAGES['en-'+resolved])
    for name in ('extra',):
        pages[name] = pages[name].replace(
            "let shade=null;const printMode",
            """let shade=null;
 const menuOverhang=5;
 const printMode"""
        ).replace(
            "menu.style.left=rect.left+'px';menu.style.top=rect.top+'px';"
            "menu.style.width=rect.width+'px';menu.style.minWidth=rect.width+'px'",
            "menu.style.left=(rect.left-menuOverhang)+'px';menu.style.top=rect.top+'px';"
            "const width=rect.width+2*menuOverhang;menu.style.width=width+'px';menu.style.minWidth=width+'px'"
        )
        pages[name] = pages[name].replace('</body>', '''<style>
html body #print-menu-shade,
html[data-snap-theme] body #print-menu-shade{
    background:transparent!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;
}
.snap-select-menu.print-menu-floating{padding:5px;border-radius:14px;--print-option-text:#283642;--print-option-highlight:#eaf7f2;--print-option-highlight-text:#26836d}
html[data-snap-theme=dark] .snap-select-menu.print-menu-floating{--print-option-text:#dce5eb;--print-option-highlight:#365449;--print-option-highlight-text:#c3e6d8}
.snap-select-menu.print-menu-floating button[role=option]{
    height:42px!important;min-height:42px!important;padding-inline:11px!important;
    border:0!important;border-radius:8px!important;box-shadow:none!important;
    background:transparent!important;color:var(--print-option-text)!important;
}
.snap-select-menu.print-menu-floating button[role=option]:hover,
.snap-select-menu.print-menu-floating:not(:has(button[role=option]:hover)) button[aria-selected=true]{
    background:var(--print-option-highlight)!important;color:var(--print-option-highlight-text)!important;
}
</style></body>''')
        pages[name] = pages[name].replace('</head>','<style>input[type=checkbox]{width:19px!important;height:19px!important;min-width:19px!important;min-height:19px!important;flex:0 0 19px!important;box-sizing:border-box}</style></head>') if '</head>' in pages[name] else pages[name].replace('</body>','<style>input[type=checkbox]{width:19px!important;height:19px!important;min-width:19px!important;min-height:19px!important;flex:0 0 19px!important;box-sizing:border-box}</style></body>')
    return pages

