_main_settings_v099 = main_settings_html
def main_settings_html(data):
    page = _main_settings_v099(data)
    page = page.replace('</body>', '<style>body{min-height:0!important;padding-bottom:12px!important}#saved{text-align:center}</style></body>')
    if data.get("cover_present") is False:
        page = page.replace('<input type="checkbox" id="allow-manual-cover">',
                            '<input type="checkbox" id="allow-manual-cover" disabled>')
    page = page.replace('</body>', """<style>
html:not(.settings-overflow),html:has(dialog[open]){overflow-y:hidden!important}
.extended-option label:has(#allow-manual-cover:disabled){opacity:.55;cursor:default}
#allow-manual-cover:disabled{cursor:default;background:transparent!important;border:1.5px solid #9aa8b2!important}
#allow-manual-cover:disabled:checked{background:#9aa8b2!important}
</style></body>""")
    # Align the selected appearance option with the closed control.
    page = page.replace(
        "const h=menu.getBoundingClientRect().height;if(printMode)",
        """if(select.id==='language'||select.id==='appearance-theme'){
 const triggerRect=trigger.getBoundingClientRect();
 const popup=menu.getBoundingClientRect();
 const item=menu.querySelector('[aria-selected=true]').getBoundingClientRect();
 const target=triggerRect.top+(triggerRect.height-item.height)/2-(item.top-popup.top);
 const top=Math.max(8,Math.min(target,innerHeight-popup.height-8));
 menu.style.top=(top-box.getBoundingClientRect().top)+'px';
 }const h=menu.getBoundingClientRect().height;if(printMode)""",
        1,
    ).replace(
        "event.key==='Escape'){",
        "event.key==='Escape'&&!document.querySelector('.snap-appearance-controls .snap-select-menu:not([hidden])')){",
    )
    page = page.replace('</body>', """<style>
.snap-appearance-controls .snap-select:has(>.snap-select-menu:not([hidden])){z-index:120}
.snap-appearance-controls .snap-select>.snap-select-menu{
    left:-5px;right:-5px;width:auto;max-width:none;padding:5px;border-radius:14px;
}
.snap-appearance-controls .snap-select>.snap-select-menu button{height:42px!important;min-height:42px!important;padding-inline:12px!important;border-radius:8px!important}
</style></body>""")
    return settings_versions_footer(page, data.get("orca_version"))


