_theme_settings_0133_base = theme_settings
AUTO_PIPELINE_CONFIRM = """<script>
(()=>{
 const checkbox = document.getElementById('auto-pipeline-setting');
 const language = document.getElementById('language');
 const dialog = document.createElement('dialog');
 dialog.id = 'expert-confirm-auto';
 dialog.setAttribute('aria-labelledby', 'auto-disable-title');
 dialog.innerHTML = '<form method="dialog"><svg class="auto-pipeline-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 2.5 20.25 7.25v9.5L12 21.5l-8.25-4.75v-9.5L12 2.5Z"/><path d="M12 8.5v7m-3.5-3.5h7"/></svg><h2 id="auto-disable-title" tabindex="-1" autofocus></h2><p></p><div class="confirm-actions"><button value="keep"></button><button value="remove"></button></div></form>';
 document.body.append(dialog);
 const copy = {
  en:['Automatic addition of\\nSnapSend is off', 'SnapSend is already in this project’s Slicing Pipeline.', 'Keep SnapSend', 'Remove from Pipeline'],
  ru:['Автодобавление SnapSend\\nотключено', 'SnapSend уже добавлен в Slicing Pipeline этого проекта.', 'Оставить', 'Убрать из Pipeline'],
  es:['Adición automática de SnapSend\\ndesactivada', 'SnapSend ya está en el Slicing Pipeline de este proyecto.', 'Mantener SnapSend', 'Quitar de Pipeline'],
  'zh-CN':['SnapSend 的自动添加\\n已关闭', '此项目的 Slicing Pipeline 已包含 SnapSend。', '保留 SnapSend', '从 Pipeline 移除'],
  ja:['SnapSend の自動追加は\\n無効です', 'このプロジェクトの Slicing Pipeline には SnapSend が追加されています。', 'SnapSend を保持', 'Pipeline から削除']
 };
 let enabled = checkbox.checked;
 let present = __PIPELINE_PRESENT__;
 window.snapAutoPipelineSaved = data=>{
  enabled = checkbox.checked;
  present = data.pipeline_present ?? present;
  window.snapRemoveAutoPipeline = false;
 };
 checkbox.addEventListener('change', ()=>{
  window.snapRemoveAutoPipeline = false;
  if(!enabled || checkbox.checked)return;
  const labels = copy[language.value] || copy.en;
  dialog.querySelector('h2').textContent = labels[0];
  const detail = {
   en:['SnapSend will no longer be added automatically to the Slicing Pipeline when you create or open a project. To use SnapSend in a project where it isn’t already in the pipeline,', 'Got it'],
   ru:['SnapSend перестанет автоматически добавляться в Slicing Pipeline проектов. Чтобы использовать его, нужно будет добавлять плагин в Slicing Pipeline вручную.', 'Понятно'],
   es:['SnapSend dejará de añadirse automáticamente. Para usarlo, añádelo manualmente a Slicing Pipeline.', 'Entendido'],
   'zh-CN':['SnapSend 将不再自动添加到项目。使用时请手动添加到 Slicing Pipeline。', '知道了'],
   ja:['SnapSend の自動追加が停止します。使うには Slicing Pipeline に手動で追加してください。', '了解']
  }[language.value] || [];
  const paragraph = dialog.querySelector('p');
  paragraph.textContent = detail[0];
  if(language.value==='en')paragraph.append(document.createElement('br'),'add it manually.');
  const removalCopy = {
   en:'SnapSend is already added to this project. You can remove it from Slicing Pipeline, but the changes will take effect after saving the settings and closing the main SnapSend window.',
   ru:'SnapSend уже добавлен в этот проект. Можно удалить его из Slicing Pipeline, но изменения вступят в силу после сохранения настроек и закрытия основного окна SnapSend.',
   es:'SnapSend ya está añadido a este proyecto. Puedes quitarlo de Slicing Pipeline, pero los cambios se aplicarán después de guardar la configuración y cerrar la ventana principal de SnapSend.',
   'zh-CN':'SnapSend 已添加到此项目。你可以将其从 Slicing Pipeline 中移除，但更改将在保存设置并关闭 SnapSend 主窗口后生效。',
   ja:'SnapSend はこのプロジェクトに追加されています。Slicing Pipeline から削除できますが、変更は設定を保存し、SnapSend のメインウィンドウを閉じた後に適用されます。'
  };
  if(present)paragraph.append(document.createElement('br'),document.createElement('br'),removalCopy[language.value] || removalCopy.en);
  const [first, second] = dialog.querySelectorAll('button');
  first.hidden = !present;
  first.value = 'keep';
  second.value = present ? 'remove' : 'disable';
  first.textContent = labels[2];
  second.textContent = present ? labels[3] : detail[1];
  dialog.returnValue = 'cancel';
  dialog.showModal();
  dialog.querySelector('h2').focus();
 });
 dialog.addEventListener('close', ()=>{
  if(dialog.returnValue==='cancel'){checkbox.checked=enabled;checkbox.dispatchEvent(new Event('change',{bubbles:true}));return}
  window.snapRemoveAutoPipeline=dialog.returnValue==='remove';
 });
})();
</script><style>
#expert-confirm-auto{max-width:min(460px,calc(100vw - 32px));padding:24px;border:1px solid var(--snap-border,#dce5eb);border-radius:22px;background:var(--snap-bg,#f6f8fa);color:var(--snap-text,#283642);text-align:center}
#expert-confirm-auto::backdrop{background:#25394c3d;backdrop-filter:blur(4px)}
#expert-confirm-auto h2:focus{outline:none}
#expert-confirm-auto h2{white-space:pre-line;margin:0 0 12px;font-weight:500;font-size:21px}
#expert-confirm-auto .confirm-actions{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:10px;width:max-content;max-width:100%;margin:0 auto}
@media(max-width:390px){#expert-confirm-auto .confirm-actions{grid-auto-flow:row;width:100%}}
#expert-confirm-auto button[hidden]{display:none!important}
#expert-confirm-auto button{margin:0!important;font-weight:400!important}
</style>"""


def current_pipeline_contains_snapsend():
    owner = SETTINGS_OWNER
    if owner is None:
        return False
    try:
        snapshot = owner.pipeline_snapshot()
        return snapshot is not None and any(ref.rsplit(";", 1)[-1] == owner.get_name()
                                            for ref in profile_values(snapshot[2]))
    except (AttributeError, RuntimeError, ValueError):
        return False


APPEARANCE_CONTROLS = '<script>\ndocument.addEventListener("DOMContentLoaded",()=>{\n const language = document.getElementById(\'language\');\n const languageLabel = document.querySelector(\'label[for="language"]\');\n const theme = document.getElementById(\'theme\');\n const oldThemeLabel = theme.closest(\'label\');\n const onboarding = document.body.classList.contains(\'onboarding\');\n const layout = document.createElement(\'div\');\n layout.className = \'snap-appearance-controls\';\n const languageWidget = language.nextElementSibling?.classList.contains(\'snap-select\') ? language.nextElementSibling : null;\n const themeLabel = document.createElement(\'label\');\n themeLabel.htmlFor = \'appearance-theme\';\n const themeText = document.createElement(\'span\');\n if(onboarding)themeLabel.innerHTML = \'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 4h14v5H3zm14 2h4v6l-9 2v3m-2 0h4v5h-4z"/></svg>\';\n themeLabel.append(themeText);\n const themeSelect = document.createElement(\'select\');\n themeSelect.id = \'appearance-theme\';\n for(const value of [\'light\',\'dark\']){\n  const option=document.createElement(\'option\');option.value=value;themeSelect.append(option);\n }\n const appearance = document.querySelector(\'.appearance-row\');\n (appearance||languageLabel).before(layout);\n layout.append(languageLabel,language);\n if(languageWidget)layout.append(languageWidget);\n layout.append(themeLabel,themeSelect);\n oldThemeLabel.hidden=true;\n if(appearance)appearance.hidden=true;\n if(onboarding){\n  const line=document.createElement(\'hr\');line.className=\'setup-divider\';\n  const autoGroup=document.querySelector(\'.auto-pipeline-group\');\n  layout.after(autoGroup);\n  autoGroup.after(line);\n  const footer=document.createElement(\'div\');footer.className=\'setup-save-area\';\n  line.after(footer);footer.append(document.getElementById(\'save\'));\n }\n const themeCopy={en:[\'Theme\',\'Light\',\'Dark\'],ru:[\'Тема\',\'Светлая\',\'Тёмная\'],es:[\'Tema\',\'Claro\',\'Oscuro\'],\'zh-CN\':[\'主题\',\'浅色\',\'深色\'],ja:[\'テーマ\',\'ライト\',\'ダーク\']};\n function syncTheme(){\n  const labels=themeCopy[language.value]||themeCopy.en;\n  themeText.textContent=labels[0];\n  themeSelect.options[0].textContent=labels[1];themeSelect.options[1].textContent=labels[2];\n  themeSelect.value=theme.checked?\'dark\':\'light\';\n  themeSelect.disabled=theme.disabled;\n  updateThemeWidget();\n }\n const updateThemeWidget=languageWidget&&typeof styleSelect===\'function\'?styleSelect(themeSelect):()=>{};\n language.addEventListener(\'change\',syncTheme);\n theme.addEventListener(\'change\',syncTheme);\n new MutationObserver(syncTheme).observe(theme,{attributes:true,attributeFilter:[\'disabled\']});\n themeSelect.addEventListener(\'change\',()=>{\n  theme.checked=themeSelect.value===\'dark\';\n  theme.dispatchEvent(new Event(\'change\',{bubbles:true}));\n });\n syncTheme();\n},{once:true});\n</script><style>\n.snap-appearance-controls{width:100%;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px 18px;align-items:center;text-align:left}\n.snap-appearance-controls label{display:flex;align-items:center;gap:10px;margin:0!important;font-weight:500}\n.snap-appearance-controls select,.snap-appearance-controls .snap-select{width:100%;min-width:0}\n.snap-appearance-controls select{height:42px}\n.snap-appearance-controls [for="language"]{grid-column:1;grid-row:1}\n.snap-appearance-controls #language,.snap-appearance-controls #language+.snap-select{grid-column:1;grid-row:2}\n.snap-appearance-controls [for="appearance-theme"]{grid-column:2;grid-row:1}\n.snap-appearance-controls #appearance-theme,.snap-appearance-controls #appearance-theme+.snap-select{grid-column:2;grid-row:2}\nbody.onboarding .snap-appearance-controls{grid-template-columns:100px minmax(0,1fr);gap:12px 12px}\nbody.onboarding .snap-appearance-controls #language{grid-column:2;grid-row:1}\nbody.onboarding .snap-appearance-controls [for="appearance-theme"]{grid-column:1;grid-row:2}\nbody.onboarding .snap-appearance-controls label svg{width:20px;height:20px;flex:none;color:var(--green,#568075)}\nbody.onboarding[data-initial-setup] .auto-pipeline-group{margin-top:20px!important;padding-top:0;border-top:0}\n.setup-divider{width:100%;border:0;border-top:1px solid var(--snap-border,#dfe6ec);margin:25px 0 0;flex:none}\nhtml body.onboarding[data-initial-setup] .snap-appearance-controls :is(#language,#appearance-theme,.snap-select-trigger){height:38px!important;min-height:38px!important;max-height:38px!important;box-sizing:border-box}\nbody.onboarding[data-initial-setup] .auto-pipeline-group input{top:2px!important}\nbody.onboarding[data-initial-setup] #auto-pipeline-title{max-width:100%}\n.setup-save-area{display:flex;align-items:center;justify-content:center;flex:1 0 68px;width:100%}\nbody.onboarding[data-initial-setup] button#save{margin:0 auto!important}\nbody:not(.onboarding) #post-section,body:not(.onboarding) #expert-section{margin-top:27px!important}\nbody:not(.onboarding) #heading{padding-bottom:22px!important}\nbody:not(.onboarding) .auto-pipeline-group input{top:2px!important}\nbody:not(.onboarding) .settings-footer{padding-top:24px;padding-bottom:12px}\nbody:not(.onboarding) #saved{position:absolute;top:calc(100% - 6px);left:0;right:0;bottom:auto;margin:0!important;height:14px;min-height:0;line-height:14px;text-align:center;pointer-events:none}\nbody:not(.onboarding) #saved:empty{visibility:hidden}\nhtml[data-snap-theme="dark"]{scrollbar-color:#46535d #20262b}\nhtml[data-snap-theme="dark"]::-webkit-scrollbar{width:8px;background:#20262b}\nhtml[data-snap-theme="dark"]::-webkit-scrollbar-thumb{background:#46535d;border-radius:8px}\n</style>'


