EXTENDED_KEYS = ('show_snapsend_tab', 'auto_pipeline', 'update_job_colors', 'allow_material_mismatch', 'allow_empty_heads', 'allow_manual_cover')
def extended_options(owner):
    config = read_native_config(owner)
    if owner is SETTINGS_OWNER and owner is not None:
        config.setdefault("auto_pipeline", owner.auto_pipeline_enabled() if hasattr(owner, "auto_pipeline_enabled") else False)
    return {k: (config.get(k) is not False if k in {'update_job_colors', 'show_snapsend_tab'} else config.get(k) is True) for k in EXTENDED_KEYS}
def assignment_options(owner):
    values = extended_options(owner)
    return {k:values[k] for k in ('allow_material_mismatch','allow_empty_heads')}
def known_material(value):
    return material(value) not in EMPTY | {'UNKNOWN', 'UNDEFINED', 'N/A', '-'}
def head_presence(head):
    if head.get('loaded') is True:
        return True
    return head.get('inserted') if type(head.get('inserted')) is bool else None
def assignment_allowed(filament, head, allow_material_mismatch=False, allow_empty_heads=False):
    if head_presence(head) is not True:
        return allow_empty_heads
    return compatible(filament, head) or allow_material_mismatch


def embedded_workspace_html(page):
    page = page.replace('class="startup-pending"', '', 1)
    page = page.replace('FILAMENT MAPPING</div>', 'Toolheads</div>', 1)
    page = page.replace('function render(){', """function render(){
 if(initial.embedded_workspace){
  $('rows').innerHTML=(heads.length?heads:[0,1,2,3].map(id=>({id}))).map(h=>
   `<article class="card"><div class="strip">Head ${h.id+1}</div>
   <div class="workspace-material"><span class="workspace-swatch" style="background:${safeColor(h.color)}"></span>
   ${esc(h.type||(h.loaded===false?'No filament reported':'—'))}</div></article>`).join('');
  return;
 }""", 1)
    start = page.index("let nativePreviewRequestCancelled")
    end = page.index("function fitPreview()", start)
    page = page[:start] + page[end:]
    page = page.replace("else request();", "else if(!initial.embedded_workspace||initial.workspace_connected)request();else $('status').textContent='Connect to the printer';", 1)
    page = page.replace("function connectionFailed(error){", """function connectionFailed(error){
 if(initial.embedded_workspace){
  connectionWaiting=false;clearTimeout(connectionTimer);busy=false;refreshing=false;
  document.body.classList.remove('refreshing-heads');setReconnecting(false);
  $('status').textContent='Printer not connected';$('status').className='status error';
  $('feedback').textContent=error||'No response from the printer.';
  $('reconnect').disabled=false;$('workspace-retry').hidden=false;
  return;
 }""", 1)
    page = page.replace("connectionTimer=setTimeout(()=>{if(seq===readSequence&&connectionWaiting)connectionFailed()},5000);", "if(!initial.embedded_workspace)connectionTimer=setTimeout(()=>{if(seq===readSequence&&connectionWaiting)connectionFailed()},5000);", 1)
    page = page.replace("function beginRead(refresh,returning=false){", "function beginRead(refresh,returning=false){$('workspace-retry').hidden=true;", 1)
    page = page.replace("function receiveLive(data){", """function receiveLive(data){
 if(Array.isArray(data.heads)){heads=data.heads;render();}
 $('workspace-retry').hidden=!data.offline;
 if(data.offline)$('feedback').textContent=data.error||'No response from the printer.';
 else if(!data.skipped)$('feedback').textContent='';""", 1)
    page = page.replace("if(Date.now()<nextPollAt", "if((initial.embedded_workspace&&(document.hidden||!$('workspace-retry').hidden))||Date.now()<nextPollAt", 1)
    page = page.replace("function updateHeaderAction(){", """function updateHeaderAction(){
 if(initial.embedded_workspace){
  $('reconnect').textContent=heads.length?'Additional settings':'Connect';
  $('head-settings').disabled=!heads.length;
  return;
 }""", 1)
    page = page.replace("render();if(initial.native_warning)", "render();updateHeaderAction();if(initial.native_warning)", 1)
    page = page.replace("$('refresh').addEventListener('click',requestRefresh);", "$('refresh').addEventListener('click',requestRefresh);$('workspace-retry').onclick=request;", 1)
    page = page.replace('<div id="feedback" role="status"></div>', '<div id="feedback" role="status"></div><button id="workspace-retry" type="button" hidden>Retry</button>', 1)
    return page


