if orca is not None:
    class U1Preview(orca.script.ScriptPluginCapabilityBase):
        def __init__(self):
            super().__init__()
            self.window = None
            self.closed = threading.Event()
            self.busy = False
            self.ready = threading.Event()
            self.draft = None
            self.applied = False
            self.send_anyway = False
            self.unassigned = []
            self.changed_heads_guard = False
            self.head_changes = ""
            self.cancel_override = False
            self.safety_warned = False
            self.result_notice_shown = False
            self.close_prompt_pending = False
            self.operation_done = threading.Event()
            self.operation_done.set()
            self.tearing_down = False

        def get_name(self):
            return "Open SnapSend"

        def on_unload(self):
            self.tearing_down = True
            self.closed.set()
            if self.window is not None:
                self.window.close()

        def execute(self, data=None, key="", config_owner=None, apply_handler=None, cancel_handler=None, override_handler=None, window_factory=None):
            if self.window is not None and self.window.is_open():
                return orca.ExecutionResult.success("The U1 preview is already open.")
            try:
                if data is None:
                    data, key = capture_profile()
                # Copy values now, on the UI thread. The worker never touches host presets.
                address = data["address"]
                owner = config_owner if config_owner is not None else SETTINGS_OWNER if SETTINGS_OWNER is not None else self
                data = dict(data, preferences=load_preferences(owner, address), debug_mode=load_debug_mode(owner), language=load_language(owner), theme=load_theme(owner), update_job_preview=read_native_config(owner).get("update_job_preview") is not False, preview_head_colors=load_preview_head_colors(owner), **extended_options(owner))
                self.closed = threading.Event()
                self.tearing_down = False
                self.ready = threading.Event()
                stop = self.closed
                window_box = {}
                pending = {"busy": False, "heads": None, "action": None, "queued": None, "suspended": False, "generation": 0}
                request_stats = {"post_count": 0}
                warning_rows = {"value": None}
                aux_cache = {}
                live = {"busy": False, "queued": None}
                v2_session = {"controller": None, "active": False}
                saved_assignments = load_assignments(owner, address)
                self.draft = None
                self.applied = False
                self.send_anyway = False
                native_offer = None
                self.changed_heads_guard = False
                self.head_changes = ""
                self.cancel_override = False
                self.safety_warned = False
                self.result_notice_shown = False
                refreshed_after_change = False
                self.unassigned = sorted({material(f["type"]) for f in data["filaments"]})

                def on_message(message):
                    nonlocal saved_assignments, refreshed_after_change
                    if isinstance(message, dict) and message.get('action') == 'prepare_native_preview':
                        if not data.get("embedded_workspace"):
                            start_native_preview(data, window_box, stop, self, pending)
                        return
                    if isinstance(message,dict) and message.get('action')=='poll_status':
                        window=window_box.get('window')
                        if stop.is_set() or self.tearing_down or pending['suspended'] or not window or not window.is_open():return
                        controller=v2_session.get('controller')
                        if live['busy'] or pending['busy'] or (controller and controller.lock.locked()):
                            window.post({'kind':'live_status','skipped':True});return
                        live['busy']=True
                        def poll_worker():
                            try:
                                client = Moonraker(address, key)
                                if data.get("embedded_workspace"):
                                    status = snapshot(client.call(WORKSPACE_LIVE_STATUS))
                                    result = dict(kind="live_status", state=status["state"], idle=status["idle"],
                                                  heads=status["heads"])
                                else:
                                    result = live_snapshot(client.call(LIVE_STATUS))
                            except Exception as error:
                                result = dict(kind="live_status", state="Unavailable", idle=False, offline=True,
                                              error=str(error) if isinstance(error, Blocked) else "No response from the printer.")
                            finally:live['busy']=False
                            queued=live['queued'];live['queued']=None
                            current=window_box.get('window')
                            if not stop.is_set() and not self.tearing_down and current is window and current.is_open():
                                if queued is None:current.post(result)
                                else:
                                    current.post({'kind':'live_status','skipped':True})
                                    on_message(queued)
                        try:threading.Thread(target=poll_worker,daemon=True).start()
                        except Exception:
                            live['busy']=False;window.post({'kind':'live_status','state':'Unavailable','idle':False,'offline':True})
                        return
                    if live['busy'] and isinstance(message,dict) and message.get('action') in ('read','validate','continue','cancel_job','send_anyway','extra_read','extra_save','heads_read','head_save','v2_action'):
                        queued=live['queued']
                        def background(value):return value.get('action')=='v2_action' and value.get('message',{}).get('action')=='read'
                        if queued is None or not background(message):live['queued']=message
                        return
                    if isinstance(message,dict) and message.get('action') in ('v2_action','v2_close') and not stop.is_set() and not self.tearing_down:
                        command = message.get('message', {})
                        current = v2_session['controller']
                        if message['action']=='v2_close':
                            if current and (current.lock.locked() or current.uncertain):return
                            v2_session['active']=False
                            return
                        if not isinstance(command,dict) or command.get('action') not in ('ready','read','save','load','unload'):return
                        win=window_box.get('window')
                        def v2_post(payload):
                            window=window_box.get('window')
                            if not stop.is_set() and v2_session['active'] and v2_session['controller'] is current and window and window.is_open():window.post({'kind':'v2_result','payload':payload})
                        if command['action']=='ready':
                            if current and current.uncertain:
                                v2_post({'kind':'error','blocked':True,'error':'Проверьте экран принтера. Повторная отправка заблокирована.'});return
                            if current and current.lock.locked():
                                v2_post({'kind':'error','blocked':current.uncertain,'error':'Запрос к принтеру ещё выполняется. Повторите действие после обновления состояния.'});return
                            v2_session['active']=True
                            client=V2_RUNTIME['V2Printer'](address,key)
                            session_window=window_box.get('window')
                            current=V2_RUNTIME['Controller'](client,v2_post,lambda:stop.is_set() or not v2_session['active'] or not session_window or not session_window.is_open(),owner)
                            v2_session['controller']=current
                        if current is None:return
                        if pending['busy'] or not current.lock.acquire(False):
                            if command['action'] in ('save','load','unload'):
                                v2_post({'kind':'error','blocked':current.uncertain,'error':'Запрос к принтеру ещё выполняется. Повторите действие после обновления состояния.'})
                            return
                        pending['busy']=True
                        self.operation_done.clear()
                        def v2_worker():
                            try:
                                if command['action']=='ready':current.initialize()
                                elif command['action']=='read':
                                    if not current.catalog or time.time()-current.catalog_at>=3600:current.initialize()
                                    else:v2_post(dict(kind='state',**current.state()))
                                else:current.perform(command)
                            except Exception as error:
                                result={'kind':'error','error':str(error),'blocked':current.uncertain}
                                try:result.update(current.state())
                                except Exception:pass
                                v2_post(result)
                            finally:
                                current.lock.release();pending['busy']=False;self.operation_done.set()
                        try:
                            threading.Thread(target=v2_worker,daemon=True).start()
                        except Exception:
                            current.lock.release();pending['busy']=False;self.operation_done.set()
                            v2_post({'kind':'error','blocked':False,'error':'Background read permission was denied. Allow threads for this plugin in OrcaSlicer and retry.'})
                        return
                    if isinstance(message,dict) and message.get("action")=="save_main_settings" and not stop.is_set() and not self.tearing_down:
                        def save_settings_worker():
                            try:
                                result=save_main_plugin_settings(owner,data,message)
                            except (AttributeError,ValueError,TypeError,RuntimeError,OSError):
                                result={"kind":"main_settings_saved","error":"Settings could not be saved."}
                            win=window_box.get("window")
                            if not stop.is_set() and win and win.is_open():
                                win.post(result)
                        threading.Thread(target=save_settings_worker,daemon=True).start()
                        return
                    if isinstance(message,dict) and message.get('action') in {'extra_read','extra_save','heads_read','head_save'} and not stop.is_set() and not self.tearing_down:
                        if pending['busy']:
                            win=window_box.get('window')
                            if win and win.is_open():
                                win.post({'kind':'extra_result' if message['action'].startswith('extra') else 'heads_result','error':'Another printer request is still running. Reopen this window.'})
                            return
                        pending['busy']=True
                        self.operation_done.clear()
                        def aux_worker():
                            kind='extra_result' if message['action'].startswith('extra') else 'heads_result'
                            try:
                                result=aux_operation(SettingsClient(address,key,owner),aux_cache,message)
                            except Exception as error:
                                result={'kind':kind,'error':str(error)}
                            finally:
                                pending['busy']=False
                                self.operation_done.set()
                            win=window_box.get('window')
                            if not stop.is_set() and not self.tearing_down and win and win.is_open():
                                win.post(result)
                        threading.Thread(target=aux_worker,daemon=True).start()
                        return
                    if self.tearing_down:
                        return
                    if isinstance(message, dict) and not stop.is_set():
                        if message.get("action") == "cancel_override":
                            self.cancel_override = message.get("value") is True
                            return
                        if message.get("action") == "result_notice":
                            self.result_notice_shown = message.get("value") is True
                            return
                        if message.get("action") == "safety_warning":
                            self.safety_warned = message.get("value") is not False
                            return
                    if isinstance(message, dict) and message.get("action") == "save_preview_colors" and not stop.is_set():
                        try:
                            data["preview_head_colors"] = save_preview_head_colors(owner, message.get("enabled"))
                        except (OSError, ValueError, TypeError, RuntimeError):
                            win = window_box.get("window")
                            if win and win.is_open():
                                win.post({"kind": "preferences_error", "error": "OrcaSlicer could not save the preview display preference."})
                        return
                    if isinstance(message, dict) and message.get("action") == "save_preferences" and "mapping" in message and not stop.is_set():
                        self.unassigned = unassigned_materials(data["filaments"], pending["heads"], message["mapping"])
                        try:
                            warning_rows["value"] = missing_assignment_rows(data["filaments"], pending["heads"] or [], message["mapping"])
                        except (Blocked, KeyError, TypeError):
                            warning_rows["value"] = None
                    if isinstance(message, dict) and message.get("action") == "save_preferences" and not stop.is_set():
                        try:
                            save_preferences(owner, address, message.get("preferences"))
                            if pending["heads"] is not None and "mapping" in message:
                                saved_assignments = save_assignments(owner, address, data["filaments"], pending["heads"], message.get("manual_mapping", {}))
                        except (OSError, ValueError, TypeError, RuntimeError):
                            win = window_box.get("window")
                            if win and win.is_open():
                                win.post({"kind": "preferences_error", "error": "OrcaSlicer could not save plugin preferences."})
                        return
                    if not isinstance(message, dict) or message.get("action") not in {"read", "validate", "continue", "cancel_job", "send_anyway"} or stop.is_set():
                        return
                    if message["action"] == "cancel_job" and self.cancel_override:
                        win = window_box.get("window")
                        if win and win.is_open():
                            win.post({"kind": "cancel_job", "cancel_prepared": True, "cancellation_skipped": True})
                        return
                    hard_reconnect = message["action"] == "read" and not message.get("refresh")
                    if pending["busy"] and not (hard_reconnect and pending["action"] == "read"):
                        if message["action"] == "read" and pending["action"] == "read":
                            pending["queued"] = message
                        return
                    if hard_reconnect:
                        pending["generation"] += 1
                        pending["queued"] = None
                        self.draft = None
                    generation = pending["generation"]
                    self.ready.set()
                    pending["action"] = message["action"]
                    pending["busy"] = True
                    checking = message["action"] == "validate"
                    if message["action"] in {"continue", "cancel_job", "send_anyway"}:
                        self.operation_done.clear()
                    def read_worker():
                        nonlocal refreshed_after_change, native_offer
                        post_before = request_stats["post_count"]
                        kind = "native_send_result" if message["action"] == "send_anyway" else "cancel_job" if message["action"] == "cancel_job" else "continue" if message["action"] == "continue" else "validation" if checking else "status"
                        payload = {"kind": kind}
                        try:
                            if not address:
                                raise Blocked("Set the U1 IP in the active profile's printer connection settings, then reopen this preview.")
                            status_client = Moonraker(address, key)
                            status_client.request_stats = request_stats
                            status_client.display_states_requested = message["action"] == "read"
                            embedded = data.get("embedded_workspace")
                            result = snapshot(status_client.call(STATUS)) if embedded else status_client.read()
                            if generation != pending["generation"] or stop.is_set():
                                return
                            payload = {"kind": kind, "heads": result["heads"], "state": result["state"], "idle": result["idle"], "raw_state": result.get("raw_state"), "can_apply": printer_waiting(result),
                                       "missing_materials": sorted({f["type"] for f in data["filaments"] if not any(compatible(f, h) for h in result["heads"])}),
                                       "manual_mapping": (manual := restore_assignments(data["filaments"], result["heads"], saved_assignments)),
                                       "mapping": suggest_mapping(data["filaments"], result["heads"], manual),
                                       "auto_mapping": suggest_mapping(data["filaments"], result["heads"]), "cover_present": result.get("cover_present"), "refresh": message.get("refresh") is True}
                            if embedded and message["action"] == "read":
                                config = read_native_config(owner)
                                if config.get("workspace_printer") != address:
                                    try:
                                        owner.save_config(json.dumps(dict(config, workspace_printer=address)))
                                    except (OSError, RuntimeError):
                                        pass
                            if message["action"] == "send_anyway":
                                if override_handler is None or native_offer is None:
                                    raise Blocked("Return to SnapSend and review the head assignments first.")
                                offer = native_offer
                                native_offer = None  # One explicit click, no retries or stale consent.
                                if result["heads"] != offer["heads"] or not printer_waiting(result):
                                    raise Blocked("Printer state or loaded materials changed. Return to SnapSend and review again.")
                                applied = override_handler(status_client, offer["mapping"], offer["prefs"], offer["cover"], offer["heads"], lambda: stop.is_set() or pending["suspended"])
                                self.send_anyway = applied.get("applied") is True
                                if self.send_anyway and not data.get("native_cancel"):
                                    self.cancel_override = True
                                payload.update(accepted=self.send_anyway)
                            if message["action"] == "read" and message.get("refresh"):
                                refreshed_after_change = True
                            if message["action"] == "cancel_job":
                                if cancel_handler is None:
                                    raise Blocked("No active upload file is available. No cancellation guard was added.")
                                missing = payload["missing_materials"] or (self.unassigned if pending["heads"] is not None else [])
                                if self.cancel_override:
                                    payload.update(cancel_prepared=True, cancellation_skipped=True)
                                    missing = []
                                if not missing and not self.cancel_override:
                                    raise Blocked("Required materials are available now. Back to setup, Refresh and assign a toolhead.")
                                if not printer_waiting(result):
                                    raise Blocked("Printer is busy or unavailable. No file changes were made. Return to setup and retry when ready.")
                                if stop.is_set():
                                    raise Blocked("Setup window closed. No cancellation guard was added.")
                                if not self.cancel_override:
                                    payload.update(cancel_handler(missing, stop.is_set))
                            if message["action"] == "continue":
                                self.unassigned = sorted({f["type"] for f in data["filaments"] if not any(h["id"] == (message.get("mapping") or {}).get(str(f["id"])) and assignment_allowed(f,h,**assignment_options(owner)) for h in result["heads"])})
                                payload["missing_materials"] = self.unassigned
                                if pending["heads"] != result["heads"]:
                                    raise HeadsChanged("Loaded filaments changed. Click Refresh and review your assignments.", pending["heads"], result["heads"])
                            if message["action"] == "continue" and printer_waiting(result) and apply_handler is not None:
                                try:
                                    if self.changed_heads_guard and not refreshed_after_change:
                                        raise HeadsChanged("Loaded filaments changed. Click Refresh and review your assignments.", pending["heads"], result["heads"])
                                    if pending["heads"] != result["heads"]:
                                        raise HeadsChanged("Loaded filaments changed. Click Refresh and review your assignments.", pending["heads"], result["heads"])
                                    chosen = validate_setup(data["filaments"], result["heads"], message.get("mapping"), message.get("prefs"), **assignment_options(owner))
                                except Blocked as exc:
                                    if isinstance(exc, HeadsChanged):
                                        self.changed_heads_guard = True
                                        self.head_changes = exc.changes if "Head " in exc.changes else self.head_changes
                                        refreshed_after_change = False
                                    payload.update(error=str(exc), review=True, heads_changed=self.changed_heads_guard, head_changes=self.head_changes)
                                    if override_handler is not None and self.unassigned and not self.changed_heads_guard:
                                        native_offer = None
                                        try:
                                            effective = native_fallback_mapping(data["filaments"], result["heads"], message.get("mapping"))
                                            validate_setup(data["filaments"], result["heads"], effective, message.get("prefs"), allow_material_mismatch=True, allow_empty_heads=True)
                                            if data.get("scope") != "plate" or data.get("warning"):
                                                raise Blocked("Valid sliced material metadata is required.")
                                            native_offer = {"heads": result["heads"], "mapping": effective, "prefs": message["prefs"], "cover": message.get("cover")}
                                            payload["native_rows"] = missing_assignment_rows(data["filaments"], result["heads"], message.get("mapping"))
                                        except Blocked as fallback_error:
                                            payload["native_blocked"] = True
                                            payload["error"] = str(fallback_error)
                                    payload["debug"] = ["Validation: FAILED"] + [name + ": no compatible loaded toolhead" for name in payload["missing_materials"]] + [str(exc), "Settings POST: NOT SENT", "Working G-code: unchanged"]
                                else:
                                    if stop.is_set() or pending["suspended"]:
                                        raise Blocked("Setup window closed before applying settings.")
                                    apply_client = Moonraker(address, key)
                                    apply_client.request_stats = request_stats
                                    applied = apply_handler(apply_client, chosen["mapping"], chosen["preferences"],
                                                            message.get("cover"), result["heads"], lambda: stop.is_set() or pending["suspended"],
                                                            job_preview=message.get('job_preview'))
                                    self.applied = applied.get("applied") is True
                                    if self.applied and refreshed_after_change:
                                        self.changed_heads_guard = False
                                    payload["applied"] = self.applied
                                    payload["debug"] = applied.get("debug", [])
                                    payload["cover_summary"] = applied.get("cover_summary", "")
                            if checking:
                                try:
                                    if pending["heads"] != result["heads"]:
                                        raise HeadsChanged("Loaded materials changed. Click Refresh and review your assignments.", pending["heads"], result["heads"])
                                    if data.get("scope") != "plate" or data.get("warning"):
                                        raise Blocked("A sliced plate with used-color metadata is required.")
                                    if not result["idle"]:
                                        raise Blocked("Printer is not ready and idle. Setup check is blocked.")
                                    self.draft = validate_setup(data["filaments"], result["heads"], message.get("mapping"), message.get("prefs"), **assignment_options(owner))
                                    payload["mapping"] = self.draft["mapping"]
                                except Blocked as exc:
                                    self.draft = None
                                    if isinstance(exc, HeadsChanged):
                                        self.changed_heads_guard = True
                                        self.head_changes = exc.changes if "Head " in exc.changes else self.head_changes
                                        refreshed_after_change = False
                                    payload["error"] = str(exc)
                            else:
                                self.draft = None
                            if message["action"] == "continue" and "debug" not in payload:
                                payload["debug"] = ["Printer state: " + str(result.get("raw_state", "unknown")),
                                                    "Settings POST: NOT SENT", "Working G-code: unchanged",
                                                    "Reason: " + ("no active Pipeline upload (preferences saved locally)" if apply_handler is None else "printer is not ready for settings"),
                                                    "Upload/start: delegated to OrcaSlicer; no Pipeline error"]
                            if message["action"] == "read":
                                payload["head_display_states"] = result.get("head_display_states", {})
                                pending["heads"] = result["heads"]
                                if message.get("refresh"):
                                    self.changed_heads_guard = False
                                    self.head_changes = ""
                            payload["heads_changed"] = self.changed_heads_guard
                            payload["head_changes"] = self.head_changes
                            selected = message.get("mapping") if message["action"] in {"continue", "validate"} else payload.get("mapping")
                            self.unassigned = sorted({f["type"] for f in data["filaments"] if not any(h["id"] == (selected or {}).get(str(f["id"])) and assignment_allowed(f,h,**assignment_options(owner)) for h in result["heads"])})
                            try:
                                payload["legacy_rows"] = warning_rows["value"] = missing_assignment_rows(data["filaments"], result["heads"], selected)
                            except (Blocked, KeyError, TypeError):
                                warning_rows["value"] = None
                        except Blocked as exc:
                            if generation != pending["generation"]:
                                return
                            self.draft = None
                            if isinstance(exc, HeadsChanged) or getattr(exc, "heads_changed", False):
                                self.changed_heads_guard = True
                                self.head_changes = (getattr(exc, "changes", "") if "Head " in getattr(exc, "changes", "") else self.head_changes)
                                refreshed_after_change = False
                            payload = {"kind": kind, "error": str(exc), "heads_changed": self.changed_heads_guard, "head_changes": self.head_changes, "review": self.changed_heads_guard, "missing_materials": self.unassigned, "debug": getattr(exc, "audit", ["Status/setup: unavailable", "No confirmed application", "No automatic retry"])}
                        except Exception:
                            if generation != pending["generation"]:
                                return
                            self.draft = None
                            payload = {"kind": kind, "error": "Could not read printer status. Check OrcaSlicer plugin permissions and the profile IP/port."}
                        finally:
                            if generation == pending["generation"]:
                                if message["action"] in {"continue", "cancel_job", "send_anyway"}:
                                    payload.setdefault("debug", []).extend([
                                        "Settings POST count (this action): " + str(request_stats["post_count"] - post_before),
                                        "Settings POST count (this window): " + str(request_stats["post_count"])])
                                pending["busy"] = False
                                if message["action"] in {"continue", "cancel_job", "send_anyway"}:
                                    self.operation_done.set()
                        if generation != pending["generation"]:
                            return
                        win = window_box.get("window")
                        if win is not None and not stop.is_set():
                            try:
                                payload["request_id"] = message.get("request_id")
                                payload["refresh"] = message.get("refresh") is True
                                if message['action'] == 'read' and (not message.get('refresh') or message.get('returning')) and data.get('thumbnail'):
                                    payload['thumbnail'] = data['thumbnail']
                                win.post(payload)
                                if not data.get("embedded_workspace") and message["action"] == "read" and (not message.get("refresh") or message.get("returning")) and not payload.get("error") and pending["queued"] is None:
                                    name = status_client.device_name()
                                    if not stop.is_set() and generation == pending["generation"]:
                                        win.post({"kind": "device_name", "request_id": message.get("request_id"), "device_name": name})
                            except Exception:
                                pass
                        queued = pending["queued"]
                        pending["queued"] = None
                        if queued is not None and not stop.is_set():
                            on_message(queued)
                    try:
                        threading.Thread(target=read_worker, name="u1-status-read", daemon=True).start()
                    except Exception:
                        pending["busy"] = False
                        self.operation_done.set()
                        win = window_box.get("window")
                        if win is not None:
                            win.post({"kind": "native_send_result" if message["action"] == "send_anyway" else "cancel_job" if message["action"] == "cancel_job" else "continue" if message["action"] == "continue" else "validation" if checking else "status", "error": "Background read permission was denied. Allow threads for this plugin in OrcaSlicer and retry."})

                def open_setup(resume=False):
                    pending["suspended"] = False
                    data.update(extended_options(owner))
                    view = dict(data, preferences=load_preferences(owner, address))
                    if resume:
                        manual = restore_assignments(data["filaments"], pending["heads"] or [], saved_assignments)
                        view.update(resume_heads=pending["heads"] or [], resume_mapping=suggest_mapping(data["filaments"], pending["heads"] or [], manual), resume_manual_mapping=manual, resume_auto_mapping=suggest_mapping(data["filaments"], pending["heads"] or []), heads_changed=self.changed_heads_guard, cancel_override=self.cancel_override)
                    factory = window_factory or orca.host.ui.create_window
                    self.window = factory(html=page_html(view), title="SnapSend", width=760, height=724,
                                    on_message=on_message, on_close=close_setup, style=orca.host.ui.WINDOW_MODAL)
                    window_box["window"] = self.window

                def close_setup():
                    pending["suspended"] = True
                    if data.get("native_cancel"):
                        stop.set()
                        return
                    if self.tearing_down or stop.is_set():
                        stop.set()
                        return
                    if (not cancel_handler or self.cancel_override or self.safety_warned or self.applied
                            or (self.result_notice_shown and not self.unassigned and not self.changed_heads_guard)):
                        stop.set()
                        return
                    self.close_prompt_pending = True
                    self.safety_warned = True
                    notice = not self.unassigned
                    returning = {"back": False}
                    def warning_message(message):
                        if self.tearing_down or stop.is_set() or not isinstance(message, dict):
                            return
                        if message.get("action") == "cancel_override":
                            self.cancel_override = message.get("value") is True
                        elif message.get("action") == "stop_notice":
                            if returning.get("writing"):
                                return
                            if pending["busy"]:
                                self.window.post({"kind": "notice_stop", "ok": False})
                                return
                            returning["writing"] = True
                            self.operation_done.clear()
                            warning_window = self.window
                            def write_notice_stop():
                                try:
                                    if notice:
                                        cancel_handler([], stop.is_set, user_requested=True)
                                    else:
                                        cancel_handler(self.unassigned, stop.is_set)
                                    # Keep Orca's send workflow paused until the file is ready.
                                    warning_window.post({"kind": "notice_stop", "ok": True})
                                except Exception:
                                    returning["writing"] = False
                                    if not stop.is_set():
                                        warning_window.post({"kind": "notice_stop", "ok": False})
                                finally:
                                    self.operation_done.set()
                            try:
                                threading.Thread(target=write_notice_stop, name="snapsend-close-stop", daemon=True).start()
                            except Exception:
                                returning["writing"] = False
                                self.operation_done.set()
                                warning_window.post({"kind": "notice_stop", "ok": False})
                        elif message.get("action") in {"cancel_job", "ack_close"}:
                            if returning.get("writing") and message.get("action") != "ack_close":
                                return
                            self.window.close()
                        elif message.get("action") == "back":
                            if returning.get("writing"):
                                return
                            returning["back"] = True
                            self.window.close()
                            self.safety_warned = False
                            open_setup(resume=True)
                    def warning_closed():
                        if not returning["back"]:
                            stop.set()
                    try:
                        self.window = orca.host.ui.create_window(html=close_warning_html(False, self.unassigned, self.cancel_override, close_notice=notice, language=data.get("language","en"), theme=data.get("theme","auto"), legacy_rows=warning_rows["value"]), title="SnapSend — " + (UNAPPLIED_NOTICE_COPY.get(data.get("language","en"), UNAPPLIED_NOTICE_COPY["en"])["title"] if notice else TRANSLATIONS.get(data.get("language","en"),{}).get("File protection", "File protection")), width=720 if notice else 680, height=614 if notice else ({"en":660,"ru":680,"es":680,"zh-CN":660,"ja":700}.get(data.get("language","en"),660)),
                                        on_message=warning_message, on_close=warning_closed, style=orca.host.ui.WINDOW_MODAL)
                        window_box["window"] = self.window
                    finally:
                        self.close_prompt_pending = False

                open_setup()
                return orca.ExecutionResult.success("U1 print setup opened.")
            except Exception as exc:
                return orca.ExecutionResult.success("Preview unavailable (%s). Continuing the standard OrcaSlicer workflow." % exc)

    class U1PipelinePreview(orca.slicing.SlicingPipelineCapabilityBase):
        def get_default_config(self):
            return {"debug_mode": False}

        def has_config_ui(self):
            return True

        def get_config_ui(self):
            return settings_config_html(self)

        def __init__(self):
            super().__init__()
            global SETTINGS_OWNER
            SETTINGS_OWNER = self
            self.preview = U1Preview()
            self._language_window = None
            self._stop_auto = threading.Event()
            self._pipeline_lock = threading.RLock()
            self._applying_auto = False
            self._committing_pipeline = False
            self._executing_pipeline = threading.Event()
            self._pipeline_schedule_lock = threading.Lock()
            self._pipeline_sync_worker = None
            self._settings_sync_worker = None
            self._settings_sync_lock = threading.Lock()

        def on_load(self):
            self._stop_auto.clear()
            self.request_settings_sync()
            show_install_language(self)
            self.apply_automatic_pipeline()

        def _save_base_config(self, config):
            return super().save_config(config)

        def save_config(self, config):
            value = json.loads(config)
            if not isinstance(value, dict):
                return False
            return save_shared_settings(self, value)

        def auto_pipeline_enabled(self):
            config = read_native_config(self)
            legacy = read_native_config(AUTO_PIPELINE_PAGE) if AUTO_PIPELINE_PAGE is not None else {}
            return config.get("auto_pipeline", legacy.get("auto_pipeline", False)) is True

        def on_lifecycle_event(self, event, ctx):
            try:
                promote_native_settings(self)
            except Exception as error:
                print("SnapSend shared settings:", error)
            lifecycle = getattr(orca, "LifecycleEvent", None)
            if lifecycle is None:
                return
            for name in ("NewProject", "ProjectOpened", "PresetSelected"):
                expected = getattr(lifecycle, name, None)
                if expected is not None and event == expected:
                    self.apply_automatic_pipeline()
                    return

        def request_settings_sync(self):
            # Process plugins has no Python save callback. Its staged override is
            # readable only after that dialog commits/closes. Observe committed
            # revisions without touching Pipeline or preset options.
            with self._settings_sync_lock:
                if self._stop_auto.is_set() or (self._settings_sync_worker is not None and self._settings_sync_worker.is_alive()):
                    return
                def reconcile_settings():
                    last_error = None
                    while not self._stop_auto.is_set():
                        try:
                            if promote_native_settings(self):
                                self.request_pipeline_sync()
                            last_error = None
                        except Exception as error:
                            message = str(error)
                            if message != last_error:
                                print("SnapSend shared settings:", message)
                                last_error = message
                        if self._stop_auto.wait(0.2):
                            return
                self._settings_sync_worker = threading.Thread(target=reconcile_settings, daemon=True)
                try:
                    self._settings_sync_worker.start()
                except PermissionError:
                    # A declined grant must not make plugin activation fail.
                    # Opening settings later retries through this same entry point.
                    self._settings_sync_worker = None
                    return False
                return True

        def request_pipeline_sync(self):
            with self._pipeline_schedule_lock:
                if self._stop_auto.is_set() or (self._pipeline_sync_worker is not None and self._pipeline_sync_worker.is_alive()):
                    return
                def reconcile():
                    while self._executing_pipeline.is_set():
                        if self._stop_auto.wait(0.1):
                            return
                    if not self._stop_auto.is_set():
                        self.apply_automatic_pipeline()
                self._pipeline_sync_worker=threading.Thread(target=reconcile,daemon=True)
                self._pipeline_sync_worker.start()

        def apply_automatic_pipeline(self):
            if self._stop_auto.is_set() or self._applying_auto or self._committing_pipeline:
                return
            if self._executing_pipeline.is_set():
                self.request_pipeline_sync()
                return
            if self._language_window is not None and self._language_window.is_open():
                return
            self._applying_auto = True
            try:
                config = read_native_config(self)
                snapshot = self.pipeline_snapshot()
                pending = config.get("pending_pipeline_removal")
                if pending:
                    if snapshot is None or list(snapshot[:2]) != pending:
                        return
                    self.update_pipeline(snapshot, remove=True)
                    config["pending_pipeline_removal"] = None
                    if self.save_config(json.dumps(config)) is False:
                        raise ValueError("Could not clear the completed Pipeline removal.")
                elif self.auto_pipeline_enabled():
                    self.update_pipeline(snapshot, automatic=True)
            except Exception as error:
                print("SnapSend automatic pipeline setup:", error)
            finally:
                self._applying_auto = False

        def pipeline_snapshot(self):
            bundle = orca.host.preset_bundle()
            printer = bundle.current_printer_preset()
            model = str(printer.config_value("printer_model") or "")
            if not re.search(r"\bU1\b", model + " " + printer.name, re.I):
                return None
            process = bundle.current_process_preset()
            return printer.name, process.name, process.config_value("slicing_pipeline_plugin") or ""

        def update_pipeline(self, snapshot, *, automatic=False, remove=False):
            with self._pipeline_lock:
                if self._executing_pipeline.is_set():
                    raise RuntimeError("Pipeline changes wait until the current SnapSend send has finished.")
                if snapshot is None:
                    return "Select a Snapmaker U1 printer profile first."
                entries = profile_values(snapshot[2])
                capability = self.get_name()
                other_entries = [ref for ref in entries if ref.rsplit(";", 1)[-1] != capability]
                present = len(other_entries) != len(entries)
                if remove and not present:
                    return "SnapSend is absent from this process."
                if not remove and present and not automatic:
                    return "SnapSend is already enabled for this process."
                if remove:
                    updated = other_entries
                else:
                    # Recommit the bare capability through Orca's picker change
                    # path, which rebuilds the resolved plugin manifest. Keep the
                    # first SnapSend position and collapse obsolete duplicates.
                    updated = []
                    inserted = False
                    for ref in entries:
                        if ref.rsplit(";", 1)[-1] == capability:
                            if not inserted:
                                updated.append(capability)
                                inserted = True
                        else:
                            updated.append(ref)
                    if not inserted:
                        updated.append(capability)
                transaction = orca.host.preset.process.begin_update()
                if self._stop_auto.is_set() or (automatic and not self.auto_pipeline_enabled()):
                    return "Automatic setup stopped."
                if self.pipeline_snapshot() != snapshot:
                    return "The printer or process changed. Try again."
                serialized = io.StringIO()
                csv.writer(serialized, delimiter=";", escapechar="\\", doublequote=False).writerow(updated)
                transaction.set("slicing_pipeline_plugin", serialized.getvalue().removesuffix("\r\n"))
                self._committing_pipeline = True
                try:
                    transaction.commit()
                finally:
                    self._committing_pipeline = False
                verified = self.pipeline_snapshot()
                if verified is None or verified[:2] != snapshot[:2]:
                    raise RuntimeError("The active process changed during the Pipeline update.")
                actual = [capability if ref.rsplit(";", 1)[-1] == capability else ref
                          for ref in profile_values(verified[2])]
                if actual != updated:
                    raise RuntimeError("OrcaSlicer did not confirm the Pipeline update.")
                return "SnapSend removed from the current process." if remove else "SnapSend refreshed in the current process." if present else "SnapSend added to the current process."

        def get_name(self):
            return "SnapSend — Upload & Print"

        def on_unload(self):
            self._stop_auto.set()
            if self._language_window is not None and self._language_window.is_open():
                self._language_window.close()
            self.preview.on_unload()

        def execute(self, ctx):
            if ctx.step != orca.slicing.Step.psGCodePostProcess:
                return orca.ExecutionResult.skipped()
            if str(ctx.host or "File").strip().lower() == "file":
                return orca.ExecutionResult.skipped("File export: no printer connection.")
            version = str(getattr(ctx, "orca_version", "") or "")
            native = native_cancel_supported(version) and callable(getattr(orca.ExecutionResult, "failure", None)) and hasattr(orca.PluginResult, "FatalError")
            def cancelled_result():
                return orca.ExecutionResult.failure(orca.PluginResult.FatalError, cancellation_message(load_language(self)))
            try:
                self._executing_pipeline.set()
                # A completed run owns its windows/callbacks; never reuse them for
                # another export after a plugin reload or a repeated Print click.
                if self.preview.closed.is_set():
                    self.preview = U1Preview()
                # Only the provided context is read on this worker. No live host handles.
                get = ctx.config_value
                identity = str(get("printer_model") or "") + " " + str(get("printer_settings_id") or "")
                if not re.search(r"\bU1\b", identity, re.I):
                    raise Blocked("Select a Snapmaker U1 profile for this pipeline.")
                address = str(get("print_host") or "").strip().strip('"')
                if not address:
                    raise Blocked("The send context contains no profile IP. Set the printer connection address and re-slice.")
                port = str(get("printhost_port") or "").strip().strip('"')
                if port:
                    parsed = urllib.parse.urlsplit(address if "://" in address else "http://" + address)
                    if parsed.port is None:
                        address = urllib.parse.urlunsplit((parsed.scheme, parsed.netloc + ":" + port, parsed.path, parsed.query, parsed.fragment))
                path = working_job_path(ctx)
                data = read_plate(path, get, ctx.output_name or "Current plate")
                data["address"] = address
                data.update(orca_version=version, native_cancel=native)
                read_job, write_job = job_io(path)
                def apply_to_job(client, mapping, prefs, cover, heads, stopped, *, job_preview=None):
                    if ctx.cancelled():
                        raise Blocked("The current send job is no longer active.")
                    config = read_native_config(self)
                    return apply_job_settings(client, dict(data, job_preview=job_preview,
                                              update_job_preview=config.get("update_job_preview") is not False,
                                              update_job_colors=config.get("update_job_colors") is not False,
                                              allow_manual_cover=config.get("allow_manual_cover") is True), mapping, prefs, cover, heads, read_job, write_job,
                                              lambda: stopped() or ctx.cancelled(), **assignment_options(self))
                def apply_override(client, mapping, prefs, cover, heads, stopped):
                    if ctx.cancelled():
                        raise Blocked("This send job does not support the explicit material override.")
                    return apply_job_settings(client, dict(data, allow_manual_cover=read_native_config(self).get("allow_manual_cover") is True),
                                              mapping, prefs, cover, heads, read_job, write_job,
                                              lambda: stopped() or ctx.cancelled(), allow_material_mismatch=True, allow_empty_heads=True)
                def cancel_job(missing, stopped, user_requested=False):
                    if stopped() or ctx.cancelled():
                        raise Blocked("Upload is no longer active. File was not changed.")
                    original = read_job()
                    prepared = prepare_user_cancel_job(original) if user_requested else prepare_cancel_job(original, missing)
                    if stopped() or ctx.cancelled():
                        raise Blocked("Upload closed before the cancellation guard was written.")
                    write_job(original, prepared)
                    return {"cancel_prepared": True, "debug": ["Required material unavailable: " + ", ".join(missing),
                            "Working G-code: CANCEL_PRINT inserted before the first executable line",
                            "Settings POST: NOT SENT", "Do not reuse this file. Load filament, re-slice and send a new file."]}
                def protect_closed_job():
                    if native or ctx.cancelled() or self.preview.cancel_override or not self.preview.unassigned:
                        return
                    original = read_job()
                    if b"; SnapSend: unavailable material cancellation guard" not in original:
                        write_job(original, prepare_cancel_job(original, self.preview.unassigned))
                result = self.preview.execute(data, str(get("printhost_apikey") or ""), config_owner=self, apply_handler=apply_to_job, cancel_handler=None if native else cancel_job, override_handler=apply_override)
                if self.preview.window is None or not self.preview.window.is_open():
                    if self.preview.window is not None:
                        self.preview.operation_done.wait()
                        protect_closed_job()
                    if native:
                        if self.preview.window is not None and not ctx.cancelled() and (self.preview.applied or self.preview.send_anyway):
                            return orca.ExecutionResult.success("Settings applied. Continuing the OrcaSlicer send workflow.")
                        return cancelled_result()
                    return orca.ExecutionResult.success("Preview unavailable. Continuing the standard OrcaSlicer send workflow.")
                started = time.monotonic()
                while not self.preview.closed.wait(0.15):
                    if ctx.cancelled() or (not self.preview.window.is_open() and not self.preview.close_prompt_pending):
                        break
                    if not self.preview.ready.is_set() and not self.preview.safety_warned and time.monotonic() - started > 20:
                        protect_closed_job()
                        if native:
                            return cancelled_result()
                        return orca.ExecutionResult.success("Preview did not appear; continuing the standard OrcaSlicer send workflow.")
                # A closed window must not release Orca while its job copy is still being edited.
                self.preview.operation_done.wait()
                protect_closed_job()
                if native and (ctx.cancelled() or not (self.preview.applied or self.preview.send_anyway)):
                    return cancelled_result()
                return orca.ExecutionResult.success("Setup closed. Continuing the standard OrcaSlicer send workflow.")
            except Exception as exc:
                if native:
                    return cancelled_result()
                return orca.ExecutionResult.success("Preview unavailable (%s). Continuing the standard OrcaSlicer send workflow." % exc)
            finally:
                if self.preview.window is not None:
                    # UiWindow.close() also invokes on_close. Teardown must not
                    # open another modal warning after the job has been released.
                    self.preview.tearing_down = True
                    self.preview.closed.set()
                    self.preview.window.close()
                    if native:
                        wait_for_native_window_close(self.preview.window)
                self._executing_pipeline.clear()

    class EmbeddedSetupWindow:
        def __init__(self, page, html, on_message, on_close):
            self.page = page
            self.on_message = on_message
            self.on_close = on_close
            self.open = True
            page._embedded_window = self
            page.post_message({"kind": "embedded_main", "html": html})

        def is_open(self):
            return self.open

        def post(self, data):
            if self.open:
                self.page.post_message({"kind": "embedded_result", "data": data})

        def close(self):
            if self.open:
                self.open = False
                self.on_close()

    if hasattr(getattr(orca, "pages", None), "PagesPluginCapabilityBase"):
        class SnapSendPage(orca.pages.PagesPluginCapabilityBase):
            def get_name(self):
                return "SnapSend"

            def get_icon(self):
                return ""

            def on_message(self, data):
                if not isinstance(data, dict):
                    return
                if data.get("action") == "embedded_ready":
                    self.embed_setup()
                    return
                if data.get("action") == "embedded_action":
                    window = getattr(self, "_embedded_window", None)
                    message = data.get("message")
                    if window is not None and window.is_open() and isinstance(message, dict):
                        if message.get("action") in {"read", "poll_status", "extra_read", "extra_save",
                                                     "v2_action", "v2_close", "save_main_settings"}:
                            window.on_message(message)
                    return
                if data.get("action") == "open_setup":
                    if not hasattr(self, "_setup") or self._setup.closed.is_set():
                        self._setup = U1Preview()
                    self._setup.execute()
                elif isinstance(data, dict) and data.get("action") == "enable_pipeline":
                    self.enable_pipeline()
                elif isinstance(data, dict) and data.get("action") == "auto_pipeline":
                    try:
                        enabled = data.get("enabled") is True
                        owner = SETTINGS_OWNER if SETTINGS_OWNER is not None else self
                        if owner.save_config(json.dumps(dict(read_native_config(owner), auto_pipeline=enabled))) is False:
                            raise Blocked("Could not save the automatic setup setting.")
                        sync_auto_pipeline(enabled)
                        message = "Automatic setup enabled for U1." if enabled else "Automatic setup disabled."
                    except Exception as error:
                        message = str(error)
                    self.post_message({"message": message, "auto": owner.auto_pipeline_enabled() if owner is SETTINGS_OWNER else read_native_config(owner).get("auto_pipeline", False)})

            def on_load(self):
                global AUTO_PIPELINE_PAGE
                AUTO_PIPELINE_PAGE = self
                self._auto_error = ""

            def on_unload(self):
                global AUTO_PIPELINE_PAGE
                if AUTO_PIPELINE_PAGE is self:
                    AUTO_PIPELINE_PAGE = None
                if hasattr(self, "_embedded_window"):
                    self._embedded_window.close()
                if hasattr(self, "_setup"):
                    self._setup.on_unload()

            def enable_pipeline(self):
                owner = SETTINGS_OWNER
                if owner is None:
                    return
                try:
                    message = owner.update_pipeline(owner.pipeline_snapshot())
                except Exception as error:
                    message = str(error)
                self.post_message({"message": message})

            def embed_setup(self):
                previous = getattr(self, "_embedded_window", None)
                if previous is not None:
                    previous.close()
                owner = SETTINGS_OWNER if SETTINGS_OWNER is not None else self
                try:
                    profile, key = capture_profile()
                except (Blocked, RuntimeError, ValueError):
                    self.post_message({"message": "Select a Snapmaker U1 printer profile and reload the workspace."})
                    return
                profile.update(embedded_workspace=True, filaments=[],
                               workspace_connected=bool(profile["address"]) and
                               read_native_config(owner).get("workspace_printer") == profile["address"])
                self._embedded_preview = U1Preview()

                def create_window(*, html, on_message, on_close, **kwargs):
                    html = html.replace("<style>", EMBEDDED_BRIDGE + "<style>", 1)
                    return EmbeddedSetupWindow(self, html, on_message, on_close)

                self._embedded_preview.execute(data=profile, key=key, config_owner=owner, window_factory=create_window)
                if not getattr(self, "_embedded_window", None) or not self._embedded_window.is_open():
                    self.post_message({"message": "Select a Snapmaker U1 printer profile and reload the workspace."})

            def get_ui(self):
                return EMBEDDED_TAB_HTML

    class SnapSendSettings(orca.script.ScriptPluginCapabilityBase):
        window = None

        def __init__(self):
            super().__init__()
            global SETTINGS_SCRIPT_OWNER
            SETTINGS_SCRIPT_OWNER = self

        def get_name(self):
            return "SnapSend Settings"

        def on_unload(self):
            if self.window is not None and self.window.is_open():
                self.window.close()
            self.window = None

        def execute(self):
            owner = SETTINGS_OWNER
            if owner is None:
                return orca.ExecutionResult.success("Activate SnapSend — Upload & Print to open settings.")
            if self.window is not None and self.window.is_open():
                return orca.ExecutionResult.success()
            promote_native_settings(owner)
            owner.apply_automatic_pipeline()
            data = dict(extended_options(owner), language=load_language(owner), theme=load_theme(owner),
                        update_job_preview=read_native_config(owner).get("update_job_preview") is not False)

            def receive(message):
                if not isinstance(message, dict) or message.get("action") != "save_language":
                    return
                window = self.window
                def save_settings_worker():
                    try:
                        result = save_main_plugin_settings(owner, data, message)
                        reply = {"kind": "saved", "pipeline_present": result["pipeline_present"]}
                    except (AttributeError, OSError, TypeError, ValueError, RuntimeError):
                        reply = {"kind": "error"}
                    if window and window.is_open():
                        window.post(reply)
                threading.Thread(target=save_settings_worker, daemon=True).start()

            html = theme_settings(data["language"], data["theme"],
                                  update_preview=data["update_job_preview"], options=data)
            self.window = orca.host.ui.create_window(html=html, title=self.get_name(),
                                                      width=560, height=735, on_message=receive)
            return orca.ExecutionResult.success()

    @orca.plugin
    class U1SendPreviewPlugin(orca.base):
        def register_capabilities(self):
            # The host requests declared grants before capability.on_load().
            orca.request_permissions(threading=True)
            orca.register_capability(U1Preview)
            orca.register_capability(U1PipelinePreview)
            orca.register_capability(SnapSendSettings)
